    // -----------------------------------------------------------------------
    // 5n. Create then Get — all fields round-trip
    // -----------------------------------------------------------------------

    #[test]
    fn dispatch_create_then_get_all_fields() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(40);

        // Create 1 tx with 3 UTXOs
        let resp = h.create_tx(txid, 3);
        assert_eq!(resp.status, STATUS_OK);

        // Get it back with ALL_METADATA mask
        let get_payload = encode_get_batch(FieldMask::ALL_METADATA, &[txid]);
        let resp = h.request(OP_GET_BATCH, get_payload);
        assert_eq!(resp.status, STATUS_OK);

        let results = decode_get_response(&resp.payload).unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].status, 0, "expected found (status=0)");

        // Decode metadata fields in order:
        // tx_version(4) + locktime(4) + fee(8) + size_in_bytes(8) + extended_size(8)
        // + flags(1) + spending_height(4) + created_at(8) + spent_utxos(4) + pruned_utxos(4)
        // + utxo_count(4) + generation(4) + updated_at(8) + unmined_since(4)
        // + delete_at_height(4) + preserve_until(4) + external_ref(65)
        // + reassignment_count(1) + block_entry_count(1)
        let data = &results[0].data;
        let mut pos = 0;

        let tx_version = u32::from_le_bytes(data[pos..pos + 4].try_into().unwrap());
        pos += 4;
        assert_eq!(tx_version, 1);

        let locktime = u32::from_le_bytes(data[pos..pos + 4].try_into().unwrap());
        pos += 4;
        assert_eq!(locktime, 0);

        let fee = u64::from_le_bytes(data[pos..pos + 8].try_into().unwrap());
        pos += 8;
        assert_eq!(fee, 500);

        let size_in_bytes = u64::from_le_bytes(data[pos..pos + 8].try_into().unwrap());
        pos += 8;
        assert_eq!(size_in_bytes, 250);

        let _extended_size = u64::from_le_bytes(data[pos..pos + 8].try_into().unwrap());
        pos += 8;

        let _flags = data[pos];
        pos += 1;

        let _spending_height = u32::from_le_bytes(data[pos..pos + 4].try_into().unwrap());
        pos += 4;

        let _created_at = u64::from_le_bytes(data[pos..pos + 8].try_into().unwrap());
        pos += 8;

        let spent_utxos = u32::from_le_bytes(data[pos..pos + 4].try_into().unwrap());
        pos += 4;
        assert_eq!(spent_utxos, 0, "no UTXOs should be spent");

        let _pruned_utxos = u32::from_le_bytes(data[pos..pos + 4].try_into().unwrap());
        pos += 4;

        let utxo_count = u32::from_le_bytes(data[pos..pos + 4].try_into().unwrap());
        assert_eq!(utxo_count, 3, "utxo_count should be 3");
        let _ = pos; // silence unused warning
    }

    /// P1-13 (end-to-end): a GET batch whose assembled COLD_DATA response
    /// would exceed MAX_FRAME_SIZE must NOT ship an oversized frame (which
    /// every conforming reader rejects, killing the connection and every
    /// pipelined request on it). `handle_get_batch` budgets the response:
    /// the item(s) that overflow come back as ERR_RESPONSE_TOO_LARGE while
    /// the records that fit still return their full cold blob, and the
    /// emitted frame is guaranteed within the wire limit.
    #[test]
    fn get_batch_over_max_frame_size_downgrades_offending_items() {
        // Five records of ~3.4 MiB inline cold data each ≈ 17 MiB of blob:
        // a COLD_DATA GET of all five would assemble past the 16 MiB limit.
        // A 256 MiB device gives ample room for the records themselves.
        let dev: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(256 * 1024 * 1024, 4096).unwrap());
        let h = DispatchTestHarness::with_device(dev);
        // A well-formed inline cold blob (inputs section only) that
        // `read_cold_data` returns whole. ~3.4 MiB each.
        let cold_data =
            crate::ops::engine::build_cold_data(Some(&vec![0xCD; 3_400_000]), None, None);
        let cold_len = cold_data.len();

        let mut txids = Vec::new();
        for i in 0..5u8 {
            let txid = DispatchTestHarness::make_txid(100 + i);
            let item = WireCreateItem {
                txid,
                tx_version: 1,
                locktime: 0,
                fee: 500,
                size_in_bytes: 250,
                extended_size: 250,
                is_coinbase: false,
                spending_height: 0,
                created_at: 1_700_000_000_000,
                flags: 0,
                utxo_hashes: vec![[i; 32]],
                cold_data: cold_data.clone(),
                block_height: 0,
                mined_block_id: None,
                mined_block_height: None,
                mined_subtree_idx: None,
                parent_txids: vec![],
            };
            assert_eq!(
                h.request(OP_CREATE_BATCH, encode_create_batch(&[item]))
                    .status,
                STATUS_OK,
                "create of record {i} with {cold_len}-byte cold data must succeed"
            );
            txids.push(txid);
        }

        let resp = h.request(OP_GET_BATCH, encode_get_batch(FieldMask::COLD_DATA, &txids));
        assert_eq!(resp.status, STATUS_OK);

        // The emitted frame MUST fit the wire budget: total_length =
        // request_id(8) + status(1) + payload.
        let inner_len = 8 + 1 + resp.payload.len();
        assert!(
            inner_len <= MAX_FRAME_SIZE as usize,
            "assembled GET response must not exceed MAX_FRAME_SIZE (got {inner_len})"
        );

        let results = decode_get_response(&resp.payload).unwrap();
        assert_eq!(results.len(), 5, "every requested item is represented");

        // At least one item overflowed and was downgraded (empty payload).
        let downgraded = results
            .iter()
            .filter(|r| r.status == ERR_RESPONSE_TOO_LARGE as u8)
            .count();
        assert!(
            downgraded >= 1,
            "at least one item must be downgraded to ERR_RESPONSE_TOO_LARGE"
        );
        for r in &results {
            if r.status == ERR_RESPONSE_TOO_LARGE as u8 {
                assert!(r.data.is_empty(), "downgraded item drops its cold blob");
            }
        }

        // The records that fit still return their FULL cold blob (status OK).
        // GET payload for a COLD_DATA-only mask is [cold_len:4][cold_bytes].
        let served_full = results
            .iter()
            .filter(|r| r.status == 0 && r.data.len() == 4 + cold_len)
            .count();
        assert!(
            served_full >= 1,
            "at least one in-budget record must return its full cold data"
        );
    }

    #[test]
    fn dispatch_get_utxo_slots_round_trips_slot_region() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(42);

        assert_eq!(h.create_tx(txid, 3).status, STATUS_OK);

        let resp = h.request(
            OP_GET_BATCH,
            encode_get_batch(FieldMask::UTXO_SLOTS, &[txid]),
        );
        assert_eq!(resp.status, STATUS_OK);
        let results = decode_get_response(&resp.payload).unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].status, STATUS_OK);

        let data = &results[0].data;
        let utxo_count = u32::from_le_bytes(data[0..4].try_into().unwrap());
        assert_eq!(utxo_count, 3);
        assert_eq!(data.len(), 4 + 3 * 69);

        let mut pos = 4;
        for i in 0..3u8 {
            let hash = &data[pos..pos + 32];
            pos += 32;
            let status = data[pos];
            pos += 1;
            let spending_data = &data[pos..pos + 36];
            pos += 36;

            assert_eq!(hash[0], i);
            assert_eq!(hash[1], 0);
            assert_eq!(status, crate::record::UTXO_UNSPENT);
            assert_eq!(spending_data, &[0u8; 36]);
        }
    }

    /// R-044 (GH-06 / GH-09) regression: an active streaming-blob
    /// upload session whose cumulative `bytes_received` would exceed
    /// the configured per-stream byte cap MUST be aborted with
    /// `ERR_STREAM_INVARIANT` (wire code 34) — the server must not accept
    /// the chunk and must not let the counter grow unbounded. Pre-fix the
    /// per-stream counter incremented on every chunk with no upper bound,
    /// so a single connection could write multi-terabyte blobs by sending
    /// 4 KiB chunks indefinitely.
    ///
    /// Test installs a 1024-byte cap on the connection state so we can
    /// exercise the rejection path without allocating gigabytes of test data.
    #[test]
    fn stream_chunk_aborts_when_cumulative_bytes_exceed_cap() {
        use crate::protocol::codec::encode_stream_chunk;
        use crate::protocol::opcodes::OP_STREAM_CHUNK;
        use crate::storage::blobstore::{BlobStore, MemoryBlobStore};

        let h = DispatchTestHarness::new();
        let blob_store: std::sync::Arc<dyn BlobStore> = std::sync::Arc::new(MemoryBlobStore::new());
        let txid = DispatchTestHarness::make_txid(0xCA);

        // Hold a single ConnectionState across two chunks, since the
        // active-stream session lives in conn_state and per-chunk
        // routing through handle_request is what production does.
        let mut conn_state =
            crate::server::ConnectionState::new().with_max_stream_total_bytes(1024);

        // Chunk 1: 800 bytes at offset 0 — under the 1024-byte cap.
        let chunk1 = vec![0xAAu8; 800];
        let req1 = RequestFrame {
            request_id: 1,
            op_code: OP_STREAM_CHUNK,
            flags: 0,
            payload: encode_stream_chunk(&txid, 0, &chunk1).into(),
        };
        let resp1 = handle_request(
            &req1,
            &h.engine,
            8192,
            None,
            None,
            &mut conn_state,
            Some(&*blob_store),
        );
        assert_eq!(
            resp1.status,
            STATUS_OK,
            "first chunk under the cap must succeed; payload: {:?}",
            String::from_utf8_lossy(&resp1.payload),
        );

        // Chunk 2: 300 bytes at offset 800 — pushes total to 1100,
        // exceeding the 1024-byte cap. MUST be rejected with wire code
        // ERR_STREAM_INVARIANT(34) (the cap check at handle_stream_chunk
        // returns ERR_STREAM_INVARIANT, not ERR_INTERNAL) and a
        // "exceeds maximum" message in the payload, and the stream session
        // must be removed.
        let chunk2 = vec![0xBBu8; 300];
        let req2 = RequestFrame {
            request_id: 2,
            op_code: OP_STREAM_CHUNK,
            flags: 0,
            payload: encode_stream_chunk(&txid, 800, &chunk2).into(),
        };
        let resp2 = handle_request(
            &req2,
            &h.engine,
            8192,
            None,
            None,
            &mut conn_state,
            Some(&*blob_store),
        );
        assert_eq!(
            resp2.status, STATUS_ERROR,
            "second chunk that pushes total over the cap must be rejected",
        );
        let (code, msg) = crate::protocol::codec::decode_error_payload(&resp2.payload)
            .expect("cap rejection must carry a typed [code:2][msg] error payload");
        assert_eq!(
            code, ERR_STREAM_INVARIANT,
            "byte-cap rejection must use wire code ERR_STREAM_INVARIANT(34); got {code}",
        );
        assert!(
            msg.contains("exceeds maximum"),
            "rejection must include the cap-exceeded reason; got: {msg}",
        );
        assert!(
            !conn_state.streams.contains_key(&txid),
            "stream session must be removed after exceeding the cap",
        );
    }

    /// REL-116: `OP_STREAM_END` whose declared `total_size` does not match the
    /// bytes actually streamed MUST be rejected with wire code
    /// `ERR_STREAM_INVARIANT(34)` (the declared-size-mismatch branch in
    /// `handle_stream_end`), the stream session MUST be removed, and the
    /// partially-written `.tmp` upload artefact MUST be cleaned up (the writer
    /// is `abort`ed). A real `FileBlobStore` is used so the `.tmp` cleanup is
    /// observable on disk, not just inferred from the in-memory map.
    #[test]
    fn stream_end_size_mismatch_aborts_and_cleans_tmp() {
        use crate::protocol::codec::{
            decode_error_payload, encode_stream_chunk, encode_stream_end,
        };
        use crate::protocol::opcodes::{OP_STREAM_CHUNK, OP_STREAM_END};
        use crate::storage::blobstore::{BlobStore, FileBlobStore};
        use std::path::Path;

        // Recursively count files under `dir` whose name ends in ".tmp".
        fn count_tmp_files(dir: &Path) -> usize {
            let mut n = 0;
            let entries = match std::fs::read_dir(dir) {
                Ok(e) => e,
                Err(_) => return 0,
            };
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    n += count_tmp_files(&path);
                } else if path
                    .file_name()
                    .and_then(|s| s.to_str())
                    .is_some_and(|s| s.ends_with(".tmp"))
                {
                    n += 1;
                }
            }
            n
        }

        let h = DispatchTestHarness::new();
        let tmp = tempfile::TempDir::new().unwrap();
        let blob_store: std::sync::Arc<dyn BlobStore> =
            std::sync::Arc::new(FileBlobStore::new(tmp.path(), 2));
        let mut conn_state = crate::server::ConnectionState::new();
        let txid = DispatchTestHarness::make_txid(0x7E);

        // Stream 10 bytes across one chunk — opens the stream and writes a
        // `.tmp` artefact to the blob store.
        let chunk = vec![0x42u8; 10];
        let chunk_req = RequestFrame {
            request_id: 1,
            op_code: OP_STREAM_CHUNK,
            flags: 0,
            payload: encode_stream_chunk(&txid, 0, &chunk).into(),
        };
        let chunk_resp = handle_request(
            &chunk_req,
            &h.engine,
            8192,
            None,
            None,
            &mut conn_state,
            Some(&*blob_store),
        );
        assert_eq!(
            chunk_resp.status,
            STATUS_OK,
            "the 10-byte chunk must be accepted; payload: {:?}",
            String::from_utf8_lossy(&chunk_resp.payload),
        );
        assert!(
            conn_state.streams.contains_key(&txid),
            "stream session must be live after the chunk",
        );
        assert_eq!(
            count_tmp_files(tmp.path()),
            1,
            "the in-progress stream must have one .tmp artefact on disk",
        );

        // STREAM_END declares 99 bytes, but only 10 were received — the
        // declared-size-mismatch branch must fire.
        let end_req = RequestFrame {
            request_id: 2,
            op_code: OP_STREAM_END,
            flags: 0,
            payload: encode_stream_end(&txid, 99).into(),
        };
        let end_resp = handle_request(
            &end_req,
            &h.engine,
            8192,
            None,
            None,
            &mut conn_state,
            Some(&*blob_store),
        );
        assert_eq!(end_resp.status, STATUS_ERROR);
        let (code, msg) = decode_error_payload(&end_resp.payload)
            .expect("size-mismatch rejection must carry a typed [code:2][msg] payload");
        assert_eq!(
            code, ERR_STREAM_INVARIANT,
            "declared-size mismatch must use wire code ERR_STREAM_INVARIANT(34); got {code}",
        );
        assert!(
            msg.contains("size mismatch"),
            "rejection must explain the size mismatch; got: {msg}",
        );

        // The session is gone and the partial writer was aborted, so the
        // `.tmp` artefact must be cleaned up — no orphaned upload debris.
        assert!(
            !conn_state.streams.contains_key(&txid),
            "stream session must be removed after the size-mismatch abort",
        );
        assert_eq!(
            count_tmp_files(tmp.path()),
            0,
            "the aborted stream's .tmp artefact must be removed from disk",
        );
        // And no committed blob exists for the txid.
        assert!(
            !blob_store.exists(&txid).unwrap(),
            "a size-mismatched stream must not finalize a blob",
        );
    }

    /// H-1/LM-1: a connection may hold at most
    /// `max_active_streams_per_connection` concurrent in-progress streams.
    /// Opening one more (a fresh txid) is rejected with `ERR_RATE_LIMITED`
    /// while the existing streams stay intact, and the rejected open must
    /// not leak a session into the map.
    #[test]
    fn stream_chunk_rejects_new_stream_past_concurrent_cap() {
        use crate::protocol::codec::{decode_error_payload, encode_stream_chunk};
        use crate::protocol::opcodes::{ERR_RATE_LIMITED, OP_STREAM_CHUNK};
        use crate::storage::blobstore::{BlobStore, MemoryBlobStore};

        let h = DispatchTestHarness::new();
        let blob_store: std::sync::Arc<dyn BlobStore> = std::sync::Arc::new(MemoryBlobStore::new());

        const CAP: usize = 4;
        let mut conn_state = crate::server::ConnectionState::new().with_max_active_streams(CAP);

        // Helper: open a new stream by sending one chunk at offset 0.
        let open_stream =
            |conn_state: &mut crate::server::ConnectionState, n: u8| -> ResponseFrame {
                let txid = DispatchTestHarness::make_txid(n);
                let req = RequestFrame {
                    request_id: n as u64,
                    op_code: OP_STREAM_CHUNK,
                    flags: 0,
                    payload: encode_stream_chunk(&txid, 0, &[0xABu8; 8]).into(),
                };
                handle_request(
                    &req,
                    &h.engine,
                    8192,
                    None,
                    None,
                    conn_state,
                    Some(&*blob_store),
                )
            };

        // Open exactly CAP distinct streams — all must succeed.
        for n in 0..CAP as u8 {
            let resp = open_stream(&mut conn_state, n);
            assert_eq!(
                resp.status,
                STATUS_OK,
                "stream {n} under the cap must be accepted; payload: {:?}",
                String::from_utf8_lossy(&resp.payload),
            );
        }
        assert_eq!(
            conn_state.streams.len(),
            CAP,
            "exactly CAP streams must be open before the rejection",
        );

        // The CAP+1-th distinct stream must be rejected with ERR_RATE_LIMITED.
        let over_txid = DispatchTestHarness::make_txid(CAP as u8);
        let resp = open_stream(&mut conn_state, CAP as u8);
        assert_eq!(
            resp.status, STATUS_ERROR,
            "opening past the concurrent-stream cap must be rejected",
        );
        let (code, msg) = decode_error_payload(&resp.payload).expect("typed error payload");
        assert_eq!(
            code, ERR_RATE_LIMITED,
            "over-cap stream open must surface ERR_RATE_LIMITED, got msg: {msg}",
        );

        // The rejected open must NOT have leaked a session (no fd/tmp would
        // have been allocated — `begin_stream` is never reached).
        assert!(
            !conn_state.streams.contains_key(&over_txid),
            "rejected over-cap stream must not appear in the session map",
        );
        assert_eq!(
            conn_state.streams.len(),
            CAP,
            "existing streams must be unaffected by the rejected open",
        );

        // An existing stream can still receive further chunks (offset 8).
        let txid0 = DispatchTestHarness::make_txid(0);
        let req = RequestFrame {
            request_id: 100,
            op_code: OP_STREAM_CHUNK,
            flags: 0,
            payload: encode_stream_chunk(&txid0, 8, &[0xCDu8; 4]).into(),
        };
        let resp = handle_request(
            &req,
            &h.engine,
            8192,
            None,
            None,
            &mut conn_state,
            Some(&*blob_store),
        );
        assert_eq!(
            resp.status, STATUS_OK,
            "existing stream must keep accepting chunks after an over-cap reject",
        );
    }

    /// H-1/LM-1: a `max_active_streams` of `0` disables the concurrent-stream
    /// cap entirely — many distinct streams open without rejection.
    #[test]
    fn stream_chunk_concurrent_cap_zero_disables_limit() {
        use crate::protocol::codec::encode_stream_chunk;
        use crate::protocol::opcodes::OP_STREAM_CHUNK;
        use crate::storage::blobstore::{BlobStore, MemoryBlobStore};

        let h = DispatchTestHarness::new();
        let blob_store: std::sync::Arc<dyn BlobStore> = std::sync::Arc::new(MemoryBlobStore::new());
        let mut conn_state = crate::server::ConnectionState::new().with_max_active_streams(0);

        for n in 0..32u8 {
            let txid = DispatchTestHarness::make_txid(n);
            let req = RequestFrame {
                request_id: n as u64,
                op_code: OP_STREAM_CHUNK,
                flags: 0,
                payload: encode_stream_chunk(&txid, 0, &[0x11u8; 2]).into(),
            };
            let resp = handle_request(
                &req,
                &h.engine,
                8192,
                None,
                None,
                &mut conn_state,
                Some(&*blob_store),
            );
            assert_eq!(
                resp.status, STATUS_OK,
                "with cap disabled, stream {n} must be accepted",
            );
        }
        assert_eq!(conn_state.streams.len(), 32, "all 32 streams must be open");
    }

    /// H-2: `reap_idle_streams` aborts streams whose `last_activity` is older
    /// than the idle timeout (removing their tmp files via `abort`), leaves a
    /// recently-active stream untouched, and a subsequent op on a reaped
    /// stream id is treated as a fresh/unknown stream — not the old session.
    #[test]
    fn reap_idle_streams_removes_only_stale_sessions() {
        use crate::protocol::codec::{
            decode_error_payload, encode_stream_chunk, encode_stream_end,
        };
        use crate::protocol::opcodes::{ERR_STREAM_NOT_FOUND, OP_STREAM_CHUNK, OP_STREAM_END};
        use crate::storage::blobstore::{BlobStore, MemoryBlobStore};
        use std::time::{Duration, Instant};

        let h = DispatchTestHarness::new();
        let blob_store: std::sync::Arc<dyn BlobStore> = std::sync::Arc::new(MemoryBlobStore::new());
        let mut conn_state = crate::server::ConnectionState::new()
            .with_stream_idle_timeout(Some(Duration::from_secs(30)));

        let stale_txid = DispatchTestHarness::make_txid(1);
        let fresh_txid = DispatchTestHarness::make_txid(2);

        // Open two streams.
        for txid in [stale_txid, fresh_txid] {
            let req = RequestFrame {
                request_id: 1,
                op_code: OP_STREAM_CHUNK,
                flags: 0,
                payload: encode_stream_chunk(&txid, 0, &[0x55u8; 4]).into(),
            };
            let resp = handle_request(
                &req,
                &h.engine,
                8192,
                None,
                None,
                &mut conn_state,
                Some(&*blob_store),
            );
            assert_eq!(resp.status, STATUS_OK, "stream open must succeed");
        }
        assert_eq!(conn_state.streams.len(), 2);

        // Backdate ONLY the stale stream's last_activity well past the
        // timeout; leave the fresh one current.
        if let Some(s) = conn_state.streams.get_mut(&stale_txid) {
            s.last_activity = Instant::now() - Duration::from_secs(120);
        }

        let reaped = conn_state.reap_idle_streams(Instant::now());
        assert_eq!(reaped, 1, "exactly the stale stream must be reaped");
        assert!(
            !conn_state.streams.contains_key(&stale_txid),
            "stale stream's map entry must be gone after reap",
        );
        assert!(
            conn_state.streams.contains_key(&fresh_txid),
            "fresh stream must survive the reap",
        );

        // OP_STREAM_END on the reaped stream id must report it as unknown —
        // the old session is gone, not silently resurrected.
        let end_req = RequestFrame {
            request_id: 9,
            op_code: OP_STREAM_END,
            flags: 0,
            payload: encode_stream_end(&stale_txid, 4).into(),
        };
        let resp = handle_stream_end(&end_req, &mut conn_state, None);
        assert_eq!(resp.status, STATUS_ERROR);
        let (code, _msg) = decode_error_payload(&resp.payload).expect("typed error payload");
        assert_eq!(
            code, ERR_STREAM_NOT_FOUND,
            "ending a reaped stream must surface ERR_STREAM_NOT_FOUND",
        );
    }

    /// H-2: a `None` idle timeout disables the reaper — a stream stamped far
    /// in the past survives `reap_idle_streams`.
    #[test]
    fn reap_idle_streams_disabled_keeps_all_sessions() {
        use crate::protocol::codec::encode_stream_chunk;
        use crate::protocol::opcodes::OP_STREAM_CHUNK;
        use crate::storage::blobstore::{BlobStore, MemoryBlobStore};
        use std::time::{Duration, Instant};

        let h = DispatchTestHarness::new();
        let blob_store: std::sync::Arc<dyn BlobStore> = std::sync::Arc::new(MemoryBlobStore::new());
        let mut conn_state = crate::server::ConnectionState::new().with_stream_idle_timeout(None);

        let txid = DispatchTestHarness::make_txid(7);
        let req = RequestFrame {
            request_id: 1,
            op_code: OP_STREAM_CHUNK,
            flags: 0,
            payload: encode_stream_chunk(&txid, 0, &[0x22u8; 4]).into(),
        };
        let resp = handle_request(
            &req,
            &h.engine,
            8192,
            None,
            None,
            &mut conn_state,
            Some(&*blob_store),
        );
        assert_eq!(resp.status, STATUS_OK);
        if let Some(s) = conn_state.streams.get_mut(&txid) {
            s.last_activity = Instant::now() - Duration::from_secs(86_400);
        }
        let reaped = conn_state.reap_idle_streams(Instant::now());
        assert_eq!(reaped, 0, "disabled reaper must not remove anything");
        assert!(
            conn_state.streams.contains_key(&txid),
            "stream must survive when the reaper is disabled",
        );
    }

    #[test]
    fn dispatch_external_create_binds_record_to_blob_digest() {
        let h = DispatchTestHarness::new();
        let blob_store = crate::storage::blobstore::MemoryBlobStore::new();
        let txid = DispatchTestHarness::make_txid(41);
        let blob_digest = blob_store
            .put(&txid, b"external transaction payload")
            .unwrap();

        let item = WireCreateItem {
            txid,
            tx_version: 1,
            locktime: 0,
            fee: 500,
            size_in_bytes: 123,
            extended_size: 123,
            is_coinbase: false,
            spending_height: 0,
            created_at: 1700000000000,
            flags: FLAG_EXTERNAL_BLOB,
            utxo_hashes: vec![[0xAB; 32]],
            cold_data: vec![],
            block_height: 0,
            mined_block_id: None,
            mined_block_height: None,
            mined_subtree_idx: None,
            parent_txids: vec![],
        };

        let resp =
            h.request_with_blob_store(OP_CREATE_BATCH, encode_create_batch(&[item]), &blob_store);
        assert_eq!(resp.status, STATUS_OK);

        let resp = h.request(
            OP_GET_BATCH,
            encode_get_batch(FieldMask::EXTERNAL_REF, &[txid]),
        );
        assert_eq!(resp.status, STATUS_OK);
        let results = decode_get_response(&resp.payload).unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].status, STATUS_OK);

        let data = &results[0].data;
        assert_eq!(data.len(), 65);
        assert_eq!(data[0], 1);
        assert_eq!(&data[1..33], &blob_digest.sha256);
        assert_eq!(
            u64::from_le_bytes(data[33..41].try_into().unwrap()),
            blob_digest.length
        );
        assert_ne!(&data[1..33], &txid);
    }

    /// FU#4 memory-bound guard: a chunked stream-read MUST use the
    /// single-hash-pass `stream_to` primitive, NOT N `get`/`get_range` calls
    /// (each of which re-reads and re-digests the ENTIRE payload — O(N²) I/O).
    #[test]
    fn stream_read_uses_stream_to_not_get_range() {
        use crate::storage::blobstore::{
            BlobDigest, BlobError, BlobStore, BlobStreamWriter, MemoryBlobStore,
        };
        use std::sync::atomic::{AtomicUsize, Ordering};

        /// BlobStore double that counts which read primitive the handler uses,
        /// delegating the actual work to an inner in-memory store.
        struct SpyBlobStore {
            inner: MemoryBlobStore,
            stream_to_calls: AtomicUsize,
            get_calls: AtomicUsize,
            get_range_calls: AtomicUsize,
            digest_calls: AtomicUsize,
        }
        impl SpyBlobStore {
            fn new() -> Self {
                Self {
                    inner: MemoryBlobStore::new(),
                    stream_to_calls: AtomicUsize::new(0),
                    get_calls: AtomicUsize::new(0),
                    get_range_calls: AtomicUsize::new(0),
                    digest_calls: AtomicUsize::new(0),
                }
            }
        }
        type BlobResult<T> = std::result::Result<T, BlobError>;
        impl BlobStore for SpyBlobStore {
            fn put(&self, key: &[u8; 32], data: &[u8]) -> BlobResult<BlobDigest> {
                self.inner.put(key, data)
            }
            fn get(&self, key: &[u8; 32]) -> BlobResult<Option<Vec<u8>>> {
                self.get_calls.fetch_add(1, Ordering::Relaxed);
                self.inner.get(key)
            }
            fn get_range(
                &self,
                key: &[u8; 32],
                offset: u64,
                length: u64,
            ) -> BlobResult<Option<Vec<u8>>> {
                self.get_range_calls.fetch_add(1, Ordering::Relaxed);
                self.inner.get_range(key, offset, length)
            }
            fn delete(&self, key: &[u8; 32]) -> BlobResult<()> {
                self.inner.delete(key)
            }
            fn exists(&self, key: &[u8; 32]) -> BlobResult<bool> {
                self.inner.exists(key)
            }
            fn digest(&self, key: &[u8; 32]) -> BlobResult<Option<BlobDigest>> {
                self.digest_calls.fetch_add(1, Ordering::Relaxed);
                self.inner.digest(key)
            }
            fn stream_to(
                &self,
                key: &[u8; 32],
                writer: &mut dyn std::io::Write,
            ) -> BlobResult<u64> {
                self.stream_to_calls.fetch_add(1, Ordering::Relaxed);
                self.inner.stream_to(key, writer)
            }
            fn begin_stream(&self, key: &[u8; 32]) -> BlobResult<Box<dyn BlobStreamWriter>> {
                self.inner.begin_stream(key)
            }
            fn list(&self) -> BlobResult<Vec<[u8; 32]>> {
                self.inner.list()
            }
        }

        let spy = SpyBlobStore::new();
        let txid = DispatchTestHarness::make_txid(77);
        // A blob spanning several chunk-target frames so a get_range-per-chunk
        // implementation would light up the get_range counter many times.
        let blob: Vec<u8> = (0..(STREAM_READ_CHUNK_TARGET * 3 + 123))
            .map(|i| (i % 256) as u8)
            .collect();
        let digest = spy.put(&txid, &blob).unwrap();

        let mut out: Vec<u8> = Vec::new();
        stream_blob_to(9, &txid, 0, &spy, &mut out).expect("stream to in-memory sink");

        // The single biggest trap: exactly one hashing pass, zero re-reads.
        assert_eq!(
            spy.stream_to_calls.load(Ordering::Relaxed),
            1,
            "must use stream_to exactly once"
        );
        assert_eq!(
            spy.get_range_calls.load(Ordering::Relaxed),
            0,
            "must NOT re-read via get_range (O(N^2) trap)"
        );
        assert_eq!(
            spy.get_calls.load(Ordering::Relaxed),
            0,
            "must NOT re-read the whole blob via get per chunk"
        );
        assert_eq!(
            spy.digest_calls.load(Ordering::Relaxed),
            1,
            "digest sidecar read once for the END trailer"
        );

        // And the emitted frames reassemble to the original blob with a
        // matching END trailer.
        let (reassembled, end) = decode_stream_frames(&out, 9);
        assert_eq!(reassembled, blob, "reassembled bytes match the source blob");
        assert_eq!(end.total_size, digest.length);
        assert_eq!(end.content_hash, digest.sha256);
    }

    /// Decode a burst of framed stream-read responses (all sharing
    /// `expect_request_id`) into (reassembled data, END trailer). Panics on any
    /// malformed frame, wrong request_id, or missing/duplicate END.
    fn decode_stream_frames(bytes: &[u8], expect_request_id: u64) -> (Vec<u8>, StreamReadEnd) {
        let mut pos = 0;
        let mut data = Vec::new();
        let mut end: Option<StreamReadEnd> = None;
        let mut next_offset = 0u64;
        while pos < bytes.len() {
            let (frame, consumed) = ResponseFrame::decode(&bytes[pos..]).expect("decode frame");
            pos += consumed;
            assert_eq!(frame.request_id, expect_request_id, "shared request_id");
            assert!(end.is_none(), "no frame may follow STATUS_STREAM_END");
            match frame.status {
                s if s == STATUS_STREAM_CHUNK => {
                    let chunk = decode_stream_read_chunk(&frame.payload).expect("chunk payload");
                    assert_eq!(chunk.offset, next_offset, "chunk offsets are contiguous");
                    next_offset += chunk.data.len() as u64;
                    data.extend_from_slice(chunk.data);
                }
                s if s == STATUS_STREAM_END => {
                    end = Some(decode_stream_read_end(&frame.payload).expect("end payload"));
                }
                other => panic!("unexpected status {other} in stream burst"),
            }
        }
        (data, end.expect("stream must end with STATUS_STREAM_END"))
    }

    /// FU#4-A: stream-read must SERVE an over-budget EXTERNAL blob locally during
    /// an OUTBOUND migration of its shard, exactly like plain GET does — the
    /// source still holds the blob until migration completes (`run_orphan_cleanup`
    /// is gated on no active/failed migration). Stream-read is the fallback for
    /// precisely the blobs GET couldn't serve whole, so it must share GET's
    /// serve-during-outbound-migration liveness.
    ///
    /// Scenario: this node is NO LONGER master for the record's shard (topology
    /// moved mastership to the target) but the shard is migrating OUTBOUND from
    /// here (`is_master == No`, `is_migrating_outbound == true`). GET serves this
    /// locally; before the fix stream-read passed `allow_if_migrating = false`
    /// and REDIRECTED the (unfetchable) blob. RED asserts no redirect / a full
    /// STREAM_CHUNK…STREAM_END burst; GREEN after `false → true`.
    #[test]
    fn stream_read_serves_during_outbound_migration_like_get() {
        use crate::cluster::shards::{NodeId, ShardTable};
        use crate::protocol::codec::{STREAM_READ_FIELD_COLD_DATA, encode_stream_read_request};
        use crate::storage::blobstore::{BlobStore, MemoryBlobStore};

        let mut h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(88);
        let payload = b"external cold-data blob served during an outbound shard migration".to_vec();

        // EXTERNAL record on THIS node's engine + its blob in the store (the
        // migration SOURCE still holds the data until migration completes).
        let blob_store: Arc<dyn BlobStore> = Arc::new(MemoryBlobStore::new());
        h.engine.set_blob_store(blob_store.clone());
        let digest = blob_store.put(&txid, &payload).unwrap();
        let item = WireCreateItem {
            txid,
            tx_version: 1,
            locktime: 0,
            fee: 0,
            size_in_bytes: payload.len() as u64,
            extended_size: payload.len() as u64,
            is_coinbase: false,
            spending_height: 0,
            created_at: 1700000000000,
            flags: FLAG_EXTERNAL_BLOB,
            utxo_hashes: vec![[0xAB; 32]],
            cold_data: vec![], // streamed — blob already in the store
            block_height: 0,
            mined_block_id: None,
            mined_block_height: None,
            mined_subtree_idx: None,
            parent_txids: vec![],
        };
        let resp =
            h.request_with_blob_store(OP_CREATE_BATCH, encode_create_batch(&[item]), &*blob_store);
        assert_eq!(resp.status, STATUS_OK, "external create must succeed");

        // 2-node cluster: self is NOT master for the record's shard, but that
        // shard is migrating OUTBOUND from here.
        let shard = ShardTable::shard_for_key(&TxKey { txid });
        let members = vec![NodeId(1), NodeId(2)];
        let table = ShardTable::compute_with_epoch(&members, 2, 11, 1);
        let master = table.target_assignment(shard).master;
        let self_id = if master == NodeId(1) {
            NodeId(2)
        } else {
            NodeId(1)
        };
        let cluster = crate::cluster::coordinator::new_test_running_cluster(
            self_id,
            table,
            &[
                (NodeId(1), "127.0.0.1:4471".parse().unwrap()),
                (NodeId(2), "127.0.0.1:4472".parse().unwrap()),
            ],
            &members,
            &[],      // inbound_shards
            &[shard], // migrating_shards — OUTBOUND migration active for this shard
            &[],      // fenced_shards
            2,
        );
        // Preconditions: not master, but migrating outbound (the FU#4-A window).
        let key = TxKey { txid };
        assert!(
            !matches!(
                cluster.is_master(&key),
                crate::cluster::coordinator::MasterQueryResult::Yes
            ),
            "precondition: self is NOT master for the shard",
        );
        assert!(
            cluster.is_migrating_outbound(&key),
            "precondition: the shard is migrating outbound from this node",
        );

        let req = RequestFrame {
            request_id: 42,
            op_code: OP_STREAM_READ,
            flags: 0,
            payload: encode_stream_read_request(&txid, STREAM_READ_FIELD_COLD_DATA, 0).into(),
        };
        let mut out: Vec<u8> = Vec::new();
        handle_stream_read(
            &req,
            &h.engine,
            &mut out,
            Some(&*blob_store),
            Some(&cluster),
        )
        .expect("stream-read must not fail at the socket layer");

        // RED (allow_if_migrating == false): a single STATUS_REDIRECT frame.
        // GREEN (== true): the full STREAM_CHUNK…STREAM_END burst.
        let (first_frame, _consumed) =
            ResponseFrame::decode(&out).expect("stream-read must emit at least one frame");
        assert_ne!(
            first_frame.status, STATUS_REDIRECT,
            "stream-read must SERVE the blob during outbound migration (parity with GET), \
             not redirect the unfetchable over-budget blob",
        );
        let (reassembled, end) = decode_stream_frames(&out, 42);
        assert_eq!(
            reassembled, payload,
            "streamed bytes must reassemble to the external blob",
        );
        assert_eq!(end.total_size, digest.length, "END trailer total_size");
        assert_eq!(end.content_hash, digest.sha256, "END trailer content_hash");
    }

    #[test]
    fn delete_external_blob_missing_rejects_before_wal_and_mutation() {
        let mut h = DispatchTestHarness::new();
        let blob_store: Arc<dyn crate::storage::blobstore::BlobStore> =
            Arc::new(crate::storage::blobstore::MemoryBlobStore::new());
        h.engine.set_blob_store(blob_store.clone());

        let txid = DispatchTestHarness::make_txid(42);
        blob_store
            .put(&txid, b"external transaction payload")
            .unwrap();

        let item = WireCreateItem {
            txid,
            tx_version: 1,
            locktime: 0,
            fee: 500,
            size_in_bytes: 123,
            extended_size: 123,
            is_coinbase: false,
            spending_height: 0,
            created_at: 1700000000000,
            flags: FLAG_EXTERNAL_BLOB,
            utxo_hashes: vec![[0xBC; 32]],
            cold_data: vec![],
            block_height: 0,
            mined_block_id: None,
            mined_block_height: None,
            mined_subtree_idx: None,
            parent_txids: vec![],
        };
        let resp =
            h.request_with_blob_store(OP_CREATE_BATCH, encode_create_batch(&[item]), &*blob_store);
        assert_eq!(resp.status, STATUS_OK);

        blob_store.delete(&txid).unwrap();

        let resp = h.request(OP_DELETE_BATCH, encode_txid_batch(&[txid], &[]));
        assert_eq!(resp.status, STATUS_PARTIAL_ERROR);
        let errors = decode_sparse_errors(&resp.payload).unwrap();
        assert_eq!(errors.len(), 1);
        assert_eq!(errors[0].item_index, 0);
        assert_eq!(errors[0].error_code, ERR_STORAGE_IO);
        assert!(String::from_utf8_lossy(&errors[0].error_data).contains("external blob missing"));

        let resp = h.request(
            OP_GET_BATCH,
            encode_get_batch(FieldMask::TX_VERSION, &[txid]),
        );
        assert_eq!(resp.status, STATUS_OK);
        let results = decode_get_response(&resp.payload).unwrap();
        assert_eq!(
            results[0].status, STATUS_OK,
            "delete must not remove the record when its external blob snapshot is missing"
        );
    }

    // -----------------------------------------------------------------------
    // Streamed external blob replication — close create-batch data loss
    // -----------------------------------------------------------------------

    /// Build the `ReplicaOp::Create` metadata_bytes for an EXTERNAL record the
    /// way `handle_create_batch`'s Phase-3 loop does: 46-byte core header,
    /// 24-byte lifecycle block, `block_height(4)` + `block_count(1)=0` +
    /// `parent_count(2)=0`, then the 65-byte `ExternalRef` tail. The receiver
    /// reconstructs the EXTERNAL record (and its `ExternalRef`) from exactly
    /// this layout.
    fn external_create_metadata_bytes(digest_sha256: [u8; 32], total_size: u64) -> Vec<u8> {
        let mut m = Vec::with_capacity(140);
        // Core 46 bytes.
        m.extend_from_slice(&1u32.to_le_bytes()); // tx_version
        m.extend_from_slice(&0u32.to_le_bytes()); // locktime
        m.extend_from_slice(&0u64.to_le_bytes()); // fee
        m.extend_from_slice(&total_size.to_le_bytes()); // size_in_bytes
        m.extend_from_slice(&total_size.to_le_bytes()); // extended_size
        m.push(0); // is_coinbase
        m.extend_from_slice(&0u32.to_le_bytes()); // spending_height
        m.extend_from_slice(&0u64.to_le_bytes()); // created_at
        m.push(0); // wire flags
        // Lifecycle 24 bytes.
        m.extend_from_slice(&0u32.to_le_bytes()); // generation
        m.extend_from_slice(&0u64.to_le_bytes()); // updated_at
        m.extend_from_slice(&0u32.to_le_bytes()); // unmined_since
        m.extend_from_slice(&0u32.to_le_bytes()); // delete_at_height
        m.extend_from_slice(&0u32.to_le_bytes()); // preserve_until
        // Extended: block_height + block_count(0) + parent_count(0).
        m.extend_from_slice(&0u32.to_le_bytes()); // block_height
        m.push(0); // mined_block_infos count
        m.extend_from_slice(&0u16.to_le_bytes()); // parent_txids count
        // ExternalRef (65 bytes): store_type + content_hash + total_size +
        // input_count + output_count + inputs_offset + outputs_offset.
        m.push(1); // store_type
        m.extend_from_slice(&digest_sha256);
        m.extend_from_slice(&total_size.to_le_bytes());
        m.extend_from_slice(&0u32.to_le_bytes()); // input_count
        m.extend_from_slice(&0u32.to_le_bytes()); // output_count
        m.extend_from_slice(&0u64.to_le_bytes()); // inputs_offset
        m.extend_from_slice(&0u64.to_le_bytes()); // outputs_offset
        m
    }

    /// Headline regression: a STREAMED external blob (`OP_STREAM_*` wrote the
    /// bytes to the master's blob store; the create's wire `cold_data` is
    /// empty) must be shipped INLINE to the replica. Before the fix the master
    /// shipped `cold_data: None`, leaving the replica with a live EXTERNAL
    /// record + ExternalRef but no blob — payload lost on promotion.
    #[test]
    fn streamed_external_create_ships_blob_to_replica() {
        use crate::record::ExternalRef;
        use crate::replication::receiver::apply_op;
        use crate::storage::blobstore::{BlobStore, MemoryBlobStore};

        let txid = DispatchTestHarness::make_txid(91);
        let payload = b"streamed external transaction payload bytes".to_vec();

        // Master: blob arrived via OP_STREAM_*, so it is already in the store
        // and the create carries an EMPTY inline cold_data. `DispatchTestHarness`
        // holds the non-reentrant global metrics test-lock for its lifetime, so
        // the master must be dropped before the replica harness is built —
        // scope it and hand the emitted op out of the block.
        let op = {
            let mut m = DispatchTestHarness::new();
            let master_store: Arc<dyn BlobStore> = Arc::new(MemoryBlobStore::new());
            m.engine.set_blob_store(master_store.clone());
            let digest = master_store.put(&txid, &payload).unwrap();

            let item = WireCreateItem {
                txid,
                tx_version: 1,
                locktime: 0,
                fee: 0,
                size_in_bytes: payload.len() as u64,
                extended_size: payload.len() as u64,
                is_coinbase: false,
                spending_height: 0,
                created_at: 1700000000000,
                flags: FLAG_EXTERNAL_BLOB,
                utxo_hashes: vec![[0xAB; 32]],
                cold_data: vec![], // streamed — empty inline body
                block_height: 0,
                mined_block_id: None,
                mined_block_height: None,
                mined_subtree_idx: None,
                parent_txids: vec![],
            };
            let resp = m.request_with_blob_store(
                OP_CREATE_BATCH,
                encode_create_batch(&[item]),
                &*master_store,
            );
            assert_eq!(
                resp.status, STATUS_OK,
                "master external create must succeed"
            );

            // Capture the cold_data the master's replica-op builder produces —
            // this is the exact production decision (`item.cold_data` is empty,
            // so the fix reads the blob back from the master store).
            let cold_data = match create_repl_cold_data(&m.engine, &txid, true, &[]) {
                CreateReplColdData::Ship(cold_data) => cold_data,
                CreateReplColdData::SkipReplicationBlobMissing => {
                    panic!("blob is present + pinned; must ship it, not skip replication")
                }
            };
            assert_eq!(
                cold_data,
                Some(payload.clone()),
                "streamed external create must ship the blob inline (was None before the fix)",
            );

            // Build the full ReplicaOp::Create the master emits.
            ReplicaOp::Create {
                tx_key: TxKey { txid },
                metadata_bytes: external_create_metadata_bytes(digest.sha256, digest.length),
                utxo_hashes: vec![[0xAB; 32]],
                cold_data,
                is_external: true,
            }
        };

        // Apply the captured op to a fresh replica.
        let mut r = DispatchTestHarness::new();
        let replica_store: Arc<dyn BlobStore> = Arc::new(MemoryBlobStore::new());
        r.engine.set_blob_store(replica_store.clone());
        apply_op(&r.engine, &op).expect("replica apply of streamed external create");

        // The replica now resolves the external payload — before the fix this
        // returned BlobNotFound.
        let got = r
            .engine
            .read_cold_data(&TxKey { txid })
            .expect("replica must resolve the external blob after apply");
        assert_eq!(
            got, payload,
            "replica external payload must match the master"
        );

        // Sanity: the replica record really is EXTERNAL with the master's ref
        // (content_hash == SHA256(payload)).
        let meta = r.engine.read_metadata(&TxKey { txid }).unwrap();
        assert!(meta.flags.contains(crate::record::TxFlags::EXTERNAL));
        let ext: ExternalRef = meta.external_ref;
        let ch = ext.content_hash;
        let mut hasher = <sha2::Sha256 as sha2::Digest>::new();
        sha2::Digest::update(&mut hasher, &payload);
        let expected: [u8; 32] = sha2::Digest::finalize(hasher).into();
        assert_eq!(ch, expected);
    }

    /// Regression guard: a NON-external create still follows the historical
    /// inline rule — empty wire body → `None`, non-empty → `Some(bytes)`.
    #[test]
    fn non_external_create_repl_cold_data_follows_inline_rule() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(92);

        match create_repl_cold_data(&h.engine, &txid, false, &[]) {
            CreateReplColdData::Ship(None) => {}
            CreateReplColdData::Ship(Some(v)) => {
                panic!("empty non-external body must ship None, got {v:?}")
            }
            CreateReplColdData::SkipReplicationBlobMissing => {
                panic!("non-external create must never skip replication")
            }
        }

        let body = vec![0x01, 0x02, 0x03, 0x04];
        match create_repl_cold_data(&h.engine, &txid, false, &body) {
            CreateReplColdData::Ship(Some(v)) => assert_eq!(v, body),
            CreateReplColdData::Ship(None) => panic!("non-empty body must ship Some"),
            CreateReplColdData::SkipReplicationBlobMissing => {
                panic!("non-external create must never skip replication")
            }
        }
    }

    /// Degraded path: an EXTERNAL item whose blob is absent from the master
    /// store must NOT ship a blob-less Create — the builder signals
    /// skip-replication (caller logs + skips the repl op while keeping the
    /// master's own create reported as success). This reproduces the
    /// should-never-happen inconsistency directly at the builder, since the
    /// create-path digest check makes the missing-blob state unreachable
    /// through the full dispatch handler.
    #[test]
    fn external_create_missing_blob_skips_replication_not_client_error() {
        use crate::storage::blobstore::{BlobStore, MemoryBlobStore};

        let txid = DispatchTestHarness::make_txid(93);

        // Blob store present but the blob is absent (intentionally not put).
        // `DispatchTestHarness` holds the global metrics test-lock for its
        // lifetime, so each harness must be dropped before the next is built
        // (the lock is not reentrant) — scope them.
        {
            let mut h = DispatchTestHarness::new();
            let store: Arc<dyn BlobStore> = Arc::new(MemoryBlobStore::new());
            h.engine.set_blob_store(store.clone());
            match create_repl_cold_data(&h.engine, &txid, true, &[]) {
                CreateReplColdData::SkipReplicationBlobMissing => {}
                CreateReplColdData::Ship(v) => {
                    panic!("missing external blob must not ship a Create, got {v:?}")
                }
            }
        }

        // No blob store configured at all: the same external item must also
        // skip (never ship a blob-less external Create).
        {
            let h2 = DispatchTestHarness::new();
            match create_repl_cold_data(&h2.engine, &txid, true, &[]) {
                CreateReplColdData::SkipReplicationBlobMissing => {}
                CreateReplColdData::Ship(v) => {
                    panic!("no blob store must not ship an external Create, got {v:?}")
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // 5o. Create, Spend, then Get — verify spent_utxos=1
    // -----------------------------------------------------------------------

    #[test]
    fn dispatch_create_spend_then_get() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(50);

        // Create with 3 UTXOs
        let resp = h.create_tx(txid, 3);
        assert_eq!(resp.status, STATUS_OK);

        // Spend UTXO at vout=0
        let mut utxo_hash = [0u8; 32];
        utxo_hash[0] = 0; // matches the hash generated in create_tx for vout=0
        let spend_params = SpendBatchParams {
            ignore_conflicting: false,
            ignore_locked: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let spend_item = WireSpendItem {
            txid,
            vout: 0,
            utxo_hash,
            spending_data: {
                let mut sd = [0u8; 36];
                sd[0] = 0xAB;
                sd[32..36].copy_from_slice(&1u32.to_le_bytes());
                sd
            },
        };
        let spend_payload = encode_spend_batch(&spend_params, &[spend_item]);
        let resp = h.request(OP_SPEND_BATCH, spend_payload);
        assert_eq!(resp.status, STATUS_OK);

        // Get and verify spent_utxos=1
        let get_payload = encode_get_batch(FieldMask::SPENT_UTXOS, &[txid]);
        let resp = h.request(OP_GET_BATCH, get_payload);
        assert_eq!(resp.status, STATUS_OK);

        let results = decode_get_response(&resp.payload).unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].status, 0);
        let spent = u32::from_le_bytes(results[0].data[0..4].try_into().unwrap());
        assert_eq!(spent, 1, "spent_utxos should be 1 after spending 1 UTXO");
    }

    // -----------------------------------------------------------------------
    // 5p. Create, SetMined, then Get — verify block_entry_count > 0
    // -----------------------------------------------------------------------

    #[test]
    fn dispatch_create_set_mined_then_get() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(60);

        let resp = h.create_tx(txid, 2);
        assert_eq!(resp.status, STATUS_OK);

        // SetMined
        let set_mined_params = SetMinedBatchParams {
            block_id: 42,
            block_height: 1000,
            subtree_idx: 0,
            on_longest_chain: true,
            unset_mined: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let set_mined_payload = encode_set_mined_batch(&set_mined_params, &[txid]);
        let resp = h.request(OP_SET_MINED_BATCH, set_mined_payload);
        assert_eq!(resp.status, STATUS_OK);

        // Get with BLOCK_ENTRY_COUNT field
        let get_payload = encode_get_batch(FieldMask::BLOCK_ENTRY_COUNT, &[txid]);
        let resp = h.request(OP_GET_BATCH, get_payload);
        assert_eq!(resp.status, STATUS_OK);

        let results = decode_get_response(&resp.payload).unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].status, 0);
        let block_entry_count = results[0].data[0];
        assert!(
            block_entry_count > 0,
            "block_entry_count should be > 0 after SetMined, got {block_entry_count}"
        );
    }

    /// Slim-index load-bearing invariant: after a full create→spend→setMined
    /// cycle a GET returns field values byte-identical to a `read_metadata` of
    /// the same record. The slim primary index caches NO metadata, so every GET
    /// field is now served from the on-device footer — this pins that GET
    /// responses are unchanged by the cache removal.
    #[test]
    fn create_spend_set_mined_get_matches_read_metadata() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(64);
        let key = TxKey { txid };

        assert_eq!(h.create_tx(txid, 3).status, STATUS_OK);

        // Spend vout 0 (utxo_hash[0] == 0 matches create_tx's generated hash).
        let mut utxo_hash = [0u8; 32];
        utxo_hash[0] = 0;
        let spend_params = SpendBatchParams {
            ignore_conflicting: false,
            ignore_locked: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let spend_item = WireSpendItem {
            txid,
            vout: 0,
            utxo_hash,
            spending_data: {
                let mut sd = [0u8; 36];
                sd[0] = 0xAB;
                sd[32..36].copy_from_slice(&1u32.to_le_bytes());
                sd
            },
        };
        assert_eq!(
            h.request(
                OP_SPEND_BATCH,
                encode_spend_batch(&spend_params, &[spend_item])
            )
            .status,
            STATUS_OK
        );

        // SetMined.
        let set_mined_params = SetMinedBatchParams {
            block_id: 42,
            block_height: 1000,
            subtree_idx: 0,
            on_longest_chain: true,
            unset_mined: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        assert_eq!(
            h.request(
                OP_SET_MINED_BATCH,
                encode_set_mined_batch(&set_mined_params, &[txid])
            )
            .status,
            STATUS_OK
        );

        // Authoritative on-device record.
        let meta = h.engine.read_metadata(&key).expect("record must exist");

        // RAW_METADATA GET returns the full footer byte-identically.
        let raw = decode_get_response(
            &h.request(
                OP_GET_BATCH,
                encode_get_batch(FieldMask::RAW_METADATA, &[txid]),
            )
            .payload,
        )
        .unwrap();
        assert_eq!(raw.len(), 1);
        assert_eq!(raw[0].status, STATUS_OK);
        let mut buf = vec![0u8; METADATA_SIZE];
        meta.to_bytes(&mut buf);
        assert_eq!(
            raw[0].data, buf,
            "RAW_METADATA GET must equal read_metadata().to_bytes()"
        );

        // Every former index-cached field, now served from the record, matches
        // read_metadata exactly.
        let get_u32 = |mask: u32| -> u32 {
            let r = decode_get_response(
                &h.request(OP_GET_BATCH, encode_get_batch(mask, &[txid]))
                    .payload,
            )
            .unwrap();
            assert_eq!(r[0].status, STATUS_OK);
            u32::from_le_bytes(r[0].data[0..4].try_into().unwrap())
        };
        assert_eq!(get_u32(FieldMask::UTXO_COUNT), { meta.utxo_count });
        assert_eq!(get_u32(FieldMask::SPENT_UTXOS), { meta.spent_utxos });
        assert_eq!(get_u32(FieldMask::GENERATION), { meta.generation });
        assert_eq!(get_u32(FieldMask::UNMINED_SINCE), { meta.unmined_since });
        assert_eq!(get_u32(FieldMask::DELETE_AT_HEIGHT), {
            meta.delete_at_height
        });

        let flags = decode_get_response(
            &h.request(OP_GET_BATCH, encode_get_batch(FieldMask::FLAGS, &[txid]))
                .payload,
        )
        .unwrap();
        assert_eq!(
            flags[0].data[0],
            { meta.flags }.bits(),
            "FLAGS must match the record footer"
        );

        // Task 16d: BLOCK_ENTRY_COUNT is a KNOWN, intentional divergence from
        // `meta.block_entry_count` (the device footer) — GET reroutes it to
        // the MinedIndex (Task 10), and `set_mined` no longer writes the
        // device's block-entry fields at all (they stay whatever they were
        // at creation, 0). The GET value must match the MinedIndex instead.
        let bec = decode_get_response(
            &h.request(
                OP_GET_BATCH,
                encode_get_batch(FieldMask::BLOCK_ENTRY_COUNT, &[txid]),
            )
            .payload,
        )
        .unwrap();
        let (mined_entries, _unmined) = h.engine.mined_block_entries(&key).unwrap();
        assert_eq!(
            bec[0].data[0] as usize,
            mined_entries.len(),
            "BLOCK_ENTRY_COUNT must match the MinedIndex, not the (intentionally stale) device \
             footer"
        );

        // Sanity: the cycle actually mutated the record (non-tautological).
        assert_eq!({ meta.spent_utxos }, 1, "one UTXO was spent");
        assert!(!mined_entries.is_empty(), "record is mined after setMined");
        assert!({ meta.generation } >= 1, "generation bumped by spend");
    }

    // -----------------------------------------------------------------------
    // Issue #30: BLOCK_ENTRIES_ALL returns the complete inline+overflow set.
    // -----------------------------------------------------------------------

    /// SetMined `txid` into each of `block_ids` (one SetMined request per
    /// distinct block), so the record accumulates one block entry per id.
    fn set_mined_into_blocks(h: &DispatchTestHarness, txid: [u8; 32], block_ids: &[u32]) {
        for (i, &block_id) in block_ids.iter().enumerate() {
            let params = SetMinedBatchParams {
                block_id,
                block_height: 1000 + i as u32,
                subtree_idx: i as u32,
                on_longest_chain: true,
                unset_mined: false,
                current_block_height: 1000,
                block_height_retention: 288,
            };
            let resp = h.request(OP_SET_MINED_BATCH, encode_set_mined_batch(&params, &[txid]));
            assert_eq!(
                resp.status, STATUS_OK,
                "SetMined into block {block_id} failed"
            );
        }
    }

    /// Decode a BLOCK_ENTRIES/BLOCK_ENTRIES_ALL section: `[count:u8]` then
    /// the entries actually present on the wire (each 12 bytes). Returns the
    /// declared count and the decoded `(block_id, block_height, subtree_idx)`
    /// tuples.
    fn decode_block_entries_section(data: &[u8]) -> (u8, Vec<(u32, u32, u32)>) {
        let count = data[0];
        let mut pos = 1;
        let mut out = Vec::new();
        while pos + 12 <= data.len() {
            let bid = u32::from_le_bytes(data[pos..pos + 4].try_into().unwrap());
            let bh = u32::from_le_bytes(data[pos + 4..pos + 8].try_into().unwrap());
            let si = u32::from_le_bytes(data[pos + 8..pos + 12].try_into().unwrap());
            out.push((bid, bh, si));
            pos += 12;
        }
        (count, out)
    }

    #[test]
    fn dispatch_block_entries_all_returns_full_overflow_set() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(80);
        assert_eq!(h.create_tx(txid, 2).status, STATUS_OK);

        // Mine into 5 distinct blocks (> INLINE_BLOCK_ENTRIES == 3), so two
        // entries land in on-device overflow.
        let block_ids = [10u32, 20, 30, 40, 50];
        set_mined_into_blocks(&h, txid, &block_ids);

        // BLOCK_ENTRIES_ALL returns all 5 entries in inline-then-overflow order.
        let resp = h.request(
            OP_GET_BATCH,
            encode_get_batch(FieldMask::BLOCK_ENTRIES_ALL, &[txid]),
        );
        assert_eq!(resp.status, STATUS_OK);
        let results = decode_get_response(&resp.payload).unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].status, 0, "expected OK status, no truncation");
        let (count, entries) = decode_block_entries_section(&results[0].data);
        assert_eq!(count, 5, "declared count should be 5");
        assert_eq!(
            entries.len(),
            5,
            "all 5 entries must be present on the wire"
        );
        // Inline slots 0..3 fill in insertion order; overflow appends 4th/5th.
        let expected: Vec<(u32, u32, u32)> = block_ids
            .iter()
            .enumerate()
            .map(|(i, &bid)| (bid, 1000 + i as u32, i as u32))
            .collect();
        assert_eq!(
            entries, expected,
            "block entries must match id/height/subtree in insertion order"
        );

        // Old BLOCK_ENTRIES field still declares count=5 but ships only 3.
        let resp = h.request(
            OP_GET_BATCH,
            encode_get_batch(FieldMask::BLOCK_ENTRIES, &[txid]),
        );
        assert_eq!(resp.status, STATUS_OK);
        let results = decode_get_response(&resp.payload).unwrap();
        let (count, entries) = decode_block_entries_section(&results[0].data);
        assert_eq!(count, 5, "BLOCK_ENTRIES still declares the true count 5");
        assert_eq!(
            entries.len(),
            3,
            "BLOCK_ENTRIES must remain capped at 3 inline (backward-compat)"
        );
        assert_eq!(
            entries,
            expected[..3].to_vec(),
            "the 3 inline entries must be the first three"
        );
    }

    /// Task 10: GET's BLOCK_ENTRIES / BLOCK_ENTRIES_ALL / BLOCK_ENTRY_COUNT /
    /// UNMINED_SINCE fields read the authoritative `ShardedMinedIndex` slot,
    /// not the device record. Task 16d: `set_mined` no longer writes the
    /// device's block-entry/unmined fields AT ALL (they stay whatever they
    /// were at creation — 0), so this now pins GET's fields against the
    /// MinedIndex directly (via `Engine::mined_block_entries`) rather than
    /// the device, including the overflow case (mining into more than
    /// `INLINE_BLOCK_ENTRIES` == 3 distinct blocks).
    #[test]
    fn get_block_fields_read_from_mined_index_match_device() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(85);
        let key = TxKey { txid };
        assert_eq!(h.create_tx(txid, 2).status, STATUS_OK);

        // Mine into 5 distinct blocks (> INLINE_BLOCK_ENTRIES == 3) on the
        // longest chain, so the record has 2 overflow entries in addition to
        // the 3 inline ones.
        let block_ids = [110u32, 220, 330, 440, 550];
        set_mined_into_blocks(&h, txid, &block_ids);

        // Authoritative source: the MinedIndex (the device's block-entry/
        // unmined fields are never written by setMined post-16d).
        let (mined_entries, mined_unmined) = h.engine.mined_block_entries(&key).unwrap();
        assert_eq!(
            mined_unmined, 0,
            "mined on the longest chain must clear unmined_since in the MinedIndex"
        );
        assert!(
            mined_entries.len() > 3,
            "test setup must actually produce more than the 3-entry wire cap"
        );
        let mined_count = mined_entries.len() as u8;

        // BLOCK_ENTRY_COUNT
        let bec = decode_get_response(
            &h.request(
                OP_GET_BATCH,
                encode_get_batch(FieldMask::BLOCK_ENTRY_COUNT, &[txid]),
            )
            .payload,
        )
        .unwrap();
        assert_eq!(bec[0].status, 0);
        assert_eq!(
            bec[0].data[0], mined_count,
            "BLOCK_ENTRY_COUNT must match the MinedIndex"
        );

        // UNMINED_SINCE
        let unmined = decode_get_response(
            &h.request(
                OP_GET_BATCH,
                encode_get_batch(FieldMask::UNMINED_SINCE, &[txid]),
            )
            .payload,
        )
        .unwrap();
        assert_eq!(unmined[0].status, 0);
        assert_eq!(
            u32::from_le_bytes(unmined[0].data[0..4].try_into().unwrap()),
            mined_unmined,
            "UNMINED_SINCE must match the MinedIndex"
        );

        let expected: Vec<(u32, u32, u32)> = block_ids
            .iter()
            .enumerate()
            .map(|(i, &bid)| (bid, 1000 + i as u32, i as u32))
            .collect();

        // BLOCK_ENTRIES: declares the true count, ships only the first 3.
        let be = decode_get_response(
            &h.request(
                OP_GET_BATCH,
                encode_get_batch(FieldMask::BLOCK_ENTRIES, &[txid]),
            )
            .payload,
        )
        .unwrap();
        assert_eq!(be[0].status, 0);
        let (count, entries) = decode_block_entries_section(&be[0].data);
        assert_eq!(
            count, mined_count,
            "BLOCK_ENTRIES declared count must match the MinedIndex"
        );
        assert_eq!(entries, expected[..3].to_vec());

        // BLOCK_ENTRIES_ALL: uncapped, must match the MinedIndex's full block set.
        let all = decode_get_response(
            &h.request(
                OP_GET_BATCH,
                encode_get_batch(FieldMask::BLOCK_ENTRIES_ALL, &[txid]),
            )
            .payload,
        )
        .unwrap();
        assert_eq!(all[0].status, 0);
        let (all_count, all_entries) = decode_block_entries_section(&all[0].data);
        assert_eq!(all_count, mined_count);
        assert_eq!(all_entries, expected);
    }

    #[test]
    fn dispatch_block_entries_all_matches_block_entries_when_under_cap() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(81);
        assert_eq!(h.create_tx(txid, 2).status, STATUS_OK);

        // Only 2 blocks (<= INLINE_BLOCK_ENTRIES): no overflow.
        set_mined_into_blocks(&h, txid, &[7u32, 9]);

        let all = {
            let resp = h.request(
                OP_GET_BATCH,
                encode_get_batch(FieldMask::BLOCK_ENTRIES_ALL, &[txid]),
            );
            let results = decode_get_response(&resp.payload).unwrap();
            assert_eq!(results[0].status, 0);
            results[0].data.clone()
        };
        let inline = {
            let resp = h.request(
                OP_GET_BATCH,
                encode_get_batch(FieldMask::BLOCK_ENTRIES, &[txid]),
            );
            let results = decode_get_response(&resp.payload).unwrap();
            assert_eq!(results[0].status, 0);
            results[0].data.clone()
        };
        assert_eq!(
            all, inline,
            "with <= 3 entries the two fields must produce byte-identical sections"
        );
        let (count, entries) = decode_block_entries_section(&all);
        assert_eq!(count, 2);
        assert_eq!(entries, vec![(7, 1000, 0), (9, 1001, 1)]);
    }

    /// Task 16d: `Engine::read_all_block_entries` (a device-only reader) was
    /// removed — it had no production caller and setMined no longer writes
    /// anything for it to read. This pins the same inline/overflow-ordering
    /// property via `Engine::mined_block_entries`, the MinedIndex-backed
    /// replacement every real reader now uses.
    #[test]
    fn mined_block_entries_inline_and_overflow_ordering() {
        let h = DispatchTestHarness::new();

        // Case 1: count <= 3 → only inline entries, no overflow.
        let txid_small = DispatchTestHarness::make_txid(82);
        assert_eq!(h.create_tx(txid_small, 2).status, STATUS_OK);
        set_mined_into_blocks(&h, txid_small, &[100u32, 200]);
        let (entries, _unmined) = h
            .engine
            .mined_block_entries(&TxKey { txid: txid_small })
            .expect("mined_block_entries should succeed for inline-only record");
        let got: Vec<(u32, u32, u32)> = entries
            .iter()
            .map(|e| (e.block_id, e.block_height, e.subtree_idx))
            .collect();
        assert_eq!(got, vec![(100, 1000, 0), (200, 1001, 1)]);

        // Case 2: count > 3 → inline + overflow, in insertion order.
        let txid_big = DispatchTestHarness::make_txid(83);
        assert_eq!(h.create_tx(txid_big, 2).status, STATUS_OK);
        let block_ids = [11u32, 22, 33, 44, 55, 66];
        set_mined_into_blocks(&h, txid_big, &block_ids);
        let (entries, _unmined) = h
            .engine
            .mined_block_entries(&TxKey { txid: txid_big })
            .expect("mined_block_entries should succeed for overflow record");
        let got: Vec<(u32, u32, u32)> = entries
            .iter()
            .map(|e| (e.block_id, e.block_height, e.subtree_idx))
            .collect();
        let expected: Vec<(u32, u32, u32)> = block_ids
            .iter()
            .enumerate()
            .map(|(i, &bid)| (bid, 1000 + i as u32, i as u32))
            .collect();
        assert_eq!(
            got, expected,
            "inline (0..3) then overflow (3..6) in insertion order"
        );
    }

