    // -----------------------------------------------------------------------
    // H10: topology vote MUST persist before reply.
    //
    // The voter persists `voted_term` / `committed_term` to disk BEFORE the
    // reply frame is constructed. If the persist fails, the reply carries
    // ERR_TOPOLOGY_PERSIST_FAILED (not STATUS_OK) so the proposer does not
    // count the vote. Without this ordering, a voter that crashed between
    // the reply and the persist could vote differently on restart →
    // split-brain.
    // -----------------------------------------------------------------------

    /// AUDIT M2.8 — a topology PROPOSE whose vote is accepted but whose
    /// persist-before-reply fails must surface `ERR_TOPOLOGY_PERSIST_FAILED`
    /// (code 23) to the proposer, not a silent STATUS_OK. (Codes 25/26/37 are
    /// already covered: `err_cluster_not_ready_gates_writes_when_joining`,
    /// the `secondary_readiness_*` suite, and `migration_transfer_request_*`.)
    #[test]
    fn topology_propose_persist_failure_returns_err_topology_persist_failed() {
        let tmp = tempfile::TempDir::new().unwrap();
        // Force persist to fail: put a regular FILE where the path's parent
        // directory would be, so ensure_parent_dir() (create_dir_all) errors
        // and persist_topology() returns Err.
        let blocker = tmp.path().join("blocker");
        std::fs::write(&blocker, b"x").unwrap();
        let path = blocker.join("node.topology");

        let h = DispatchTestHarness::new();
        let self_id = crate::cluster::shards::NodeId(1);
        let other = crate::cluster::shards::NodeId(2);
        let members = vec![self_id, other];
        let table = crate::cluster::shards::ShardTable::compute_with_epoch(&[self_id], 1, 10, 1);
        let cluster = crate::cluster::coordinator::new_test_running_cluster_with_topology_path(
            self_id,
            table,
            &[(self_id, "127.0.0.1:4720".parse().unwrap())],
            &[self_id],
            &[],
            &[],
            &[],
            1,
            Some(path.clone()),
        );
        cluster
            .topology_authority()
            .set_committed_voter_ever_seen(&[self_id, other]);

        // A subsuming proposal that handle_propose accepts (same shape as
        // topology_vote_persisted_before_reply), so the accepted-vote +
        // failed-persist branch is exercised.
        let propose = crate::cluster::topology::TopologyTerm::new(
            500,
            members.clone(),
            other,
            crate::cluster::topology::ClusterId::UNSET,
            1,
            (members.clone()).len() as u64,
        );
        let req = RequestFrame {
            request_id: 1,
            op_code: OP_TOPOLOGY_PROPOSE,
            flags: 0,
            payload: propose.serialize().into(),
        };
        let mut conn_state = crate::server::ConnectionState::new();
        let resp = handle_request(
            &req,
            &h.engine,
            8192,
            Some(&cluster),
            None,
            &mut conn_state,
            None,
        );

        assert_eq!(
            resp.status, STATUS_ERROR,
            "an accepted vote whose persist fails must return STATUS_ERROR",
        );
        assert_eq!(
            extract_err(&resp),
            ERR_TOPOLOGY_PERSIST_FAILED,
            "persist failure must surface code 23",
        );
    }

    #[test]
    fn topology_vote_persisted_before_reply() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("node.topology");

        let h = DispatchTestHarness::new();
        let self_id = crate::cluster::shards::NodeId(1);
        let other = crate::cluster::shards::NodeId(2);
        let members = vec![self_id, other];
        let table = crate::cluster::shards::ShardTable::compute_with_epoch(&[self_id], 1, 10, 1);
        let cluster = crate::cluster::coordinator::new_test_running_cluster_with_topology_path(
            self_id,
            table,
            &[(self_id, "127.0.0.1:4710".parse().unwrap())],
            &[self_id],
            &[],
            &[],
            &[],
            1,
            Some(path.clone()),
        );
        // F-G8-001: handle_propose now rejects any proposal that
        // introduces a NodeId the voter has never seen as a committed
        // voter. Pre-seed the ever-seen set with both members so the
        // subsume proposal is accepted and we can exercise the vote-
        // persist-before-reply path the test actually targets.
        cluster
            .topology_authority()
            .set_committed_voter_ever_seen(&[self_id, other]);

        // Propose a new term that subsumes this single-node cluster.
        let proposer = other;
        let propose = crate::cluster::topology::TopologyTerm::new(
            500,
            members.clone(),
            proposer,
            crate::cluster::topology::ClusterId::UNSET,
            1,
            (members.clone()).len() as u64,
        );

        let req = RequestFrame {
            request_id: 1,
            op_code: OP_TOPOLOGY_PROPOSE,
            flags: 0,
            payload: propose.serialize().into(),
        };
        let mut conn_state = crate::server::ConnectionState::new();
        let resp = handle_request(
            &req,
            &h.engine,
            8192,
            Some(&cluster),
            None,
            &mut conn_state,
            None,
        );

        assert_eq!(resp.status, STATUS_OK, "propose should be accepted");
        // Decode the vote and confirm we accepted.
        let vote = crate::cluster::topology::TopologyVote::deserialize(&resp.payload)
            .expect("vote must deserialize");
        assert!(
            vote.accepted,
            "vote must be accepted for subsuming proposal"
        );
        assert_eq!(vote.term, 500);

        // The reply has already been returned by handle_request. The
        // safety invariant: by the time the caller observes the reply,
        // the on-disk state MUST contain voted_term=500.
        let persisted = crate::cluster::coordinator::load_topology_state(&path);
        assert_eq!(
            persisted.voted_term, 500,
            "voted_term must be persisted BEFORE the reply is observable; \
             found {} on disk after reply returned",
            persisted.voted_term,
        );
    }

    #[test]
    fn topology_vote_reply_failure_surfaces_persist_error() {
        // Point topology_state_path at a non-existent parent directory —
        // File::create will fail, persist_topology() returns Err, and the
        // vote handler must respond with ERR_TOPOLOGY_PERSIST_FAILED rather
        // than acking the vote.
        let bogus = std::path::PathBuf::from("/nonexistent/teraslab-topology-h10/node.topology");
        let h = DispatchTestHarness::new();
        let self_id = crate::cluster::shards::NodeId(1);
        let other = crate::cluster::shards::NodeId(2);
        let members = vec![self_id, other];
        let table = crate::cluster::shards::ShardTable::compute_with_epoch(&[self_id], 1, 10, 1);
        let cluster = crate::cluster::coordinator::new_test_running_cluster_with_topology_path(
            self_id,
            table,
            &[(self_id, "127.0.0.1:4711".parse().unwrap())],
            &[self_id],
            &[],
            &[],
            &[],
            1,
            Some(bogus),
        );
        // F-G8-001: pre-seed the ever-seen set so the subsume proposal
        // is accepted by handle_propose and we exercise the persist-
        // failure path (rather than failing earlier on split-brain).
        cluster
            .topology_authority()
            .set_committed_voter_ever_seen(&[self_id, other]);

        let proposer = other;
        let propose = crate::cluster::topology::TopologyTerm::new(
            600,
            members.clone(),
            proposer,
            crate::cluster::topology::ClusterId::UNSET,
            1,
            (members.clone()).len() as u64,
        );

        let req = RequestFrame {
            request_id: 1,
            op_code: OP_TOPOLOGY_PROPOSE,
            flags: 0,
            payload: propose.serialize().into(),
        };
        let mut conn_state = crate::server::ConnectionState::new();
        let resp = handle_request(
            &req,
            &h.engine,
            8192,
            Some(&cluster),
            None,
            &mut conn_state,
            None,
        );

        assert_eq!(
            resp.status, STATUS_ERROR,
            "persist failure must surface as error"
        );
        assert!(resp.payload.len() >= 2);
        let err_code = u16::from_le_bytes(resp.payload[..2].try_into().unwrap());
        assert_eq!(
            err_code, ERR_TOPOLOGY_PERSIST_FAILED,
            "expected ERR_TOPOLOGY_PERSIST_FAILED, got {err_code}"
        );
    }

    #[test]
    fn topology_commit_persisted_before_reply() {
        // Committing a new term must also persist before the reply so
        // restart-after-crash observes the committed term.
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("node.topology");

        let h = DispatchTestHarness::new();
        let self_id = crate::cluster::shards::NodeId(1);
        let members = vec![self_id, crate::cluster::shards::NodeId(2)];
        // Start from a cluster already at term 10 (single-node).
        let table = crate::cluster::shards::ShardTable::compute_with_epoch(&[self_id], 1, 10, 1);
        let cluster = crate::cluster::coordinator::new_test_running_cluster_with_topology_path(
            self_id,
            table,
            &[(self_id, "127.0.0.1:4712".parse().unwrap())],
            &[self_id],
            &[],
            &[],
            &[],
            1,
            Some(path.clone()),
        );

        // E-2: the commit-apply guard now mirrors the propose side, so the
        // {1} → {1,2} growth (which introduces unseen node 2) requires a
        // matching cluster_id; the ever-seen fallback would otherwise
        // reject it when cluster_id is unset.
        let cid = crate::cluster::topology::ClusterId([0x5B; 16]);
        cluster.topology_authority().set_cluster_id(cid);

        // Step 1: accept a proposal (sets voted_term).
        let proposer = crate::cluster::shards::NodeId(2);
        let propose = crate::cluster::topology::TopologyTerm::new(
            700,
            members.clone(),
            proposer,
            cid,
            1,
            (members.clone()).len() as u64,
        );
        let req = RequestFrame {
            request_id: 1,
            op_code: OP_TOPOLOGY_PROPOSE,
            flags: 0,
            payload: propose.serialize().into(),
        };
        let mut conn_state = crate::server::ConnectionState::new();
        let resp = handle_request(
            &req,
            &h.engine,
            8192,
            Some(&cluster),
            None,
            &mut conn_state,
            None,
        );
        assert_eq!(resp.status, STATUS_OK);

        // Step 2: commit that term.
        let commit = crate::cluster::topology::TopologyCommit {
            term: 700,
            proposer,
            members: members.clone(),
            cluster_id: cid,
            placement_version: 1,
            committed_peak: (members.clone()).len() as u64,
            digest: crate::cluster::topology::TopologyTerm::compute_digest(
                700,
                &cid,
                &members,
                1,
                (members).len() as u64,
            ),
            voters: members.clone(),
        };
        let req = RequestFrame {
            request_id: 2,
            op_code: OP_TOPOLOGY_COMMIT,
            flags: 0,
            payload: commit.serialize().into(),
        };
        let resp = handle_request(
            &req,
            &h.engine,
            8192,
            Some(&cluster),
            None,
            &mut conn_state,
            None,
        );
        assert_eq!(resp.status, STATUS_OK, "commit must succeed");

        // By the time the reply is visible, committed_term=700 must be on disk.
        let persisted = crate::cluster::coordinator::load_topology_state(&path);
        assert_eq!(
            persisted.committed_term, 700,
            "committed_term must be persisted before the commit reply returns"
        );
        assert_eq!(persisted.committed_members, members);
    }

    #[test]
    fn deleted_topo_file_prevents_single_node_bootstrap() {
        let tmp = tempfile::TempDir::new().unwrap();
        let cluster_state_path = tmp.path().join("node.cluster");
        let topology_path =
            crate::cluster::coordinator::topology_state_path_for_cluster_state(&cluster_state_path);
        let self_id = crate::cluster::shards::NodeId(1);
        let prior_members = vec![
            self_id,
            crate::cluster::shards::NodeId(2),
            crate::cluster::shards::NodeId(3),
        ];
        let prior_table =
            crate::cluster::shards::ShardTable::compute_with_epoch(&prior_members, 1, 9, 1);
        let prior_cluster =
            crate::cluster::coordinator::new_test_running_cluster_with_topology_path(
                self_id,
                prior_table,
                &[(self_id, "127.0.0.1:4801".parse().unwrap())],
                &prior_members,
                &[],
                &[],
                &[],
                3,
                Some(topology_path.clone()),
            );
        prior_cluster
            .persist_topology()
            .expect("multi-node topology marker should persist");
        std::fs::remove_file(&topology_path).expect("delete persisted topology file");

        let restored =
            crate::cluster::coordinator::load_startup_topology_state(&cluster_state_path);
        assert!(
            restored.peak_cluster_size >= 2,
            "deleted .topo must not erase local multi-node evidence; restored peak={}",
            restored.peak_cluster_size,
        );

        let h = DispatchTestHarness::new();
        let fresh_single_node_table =
            crate::cluster::shards::ShardTable::compute_with_epoch(&[self_id], 1, 1, 1);
        let rebooted_cluster = crate::cluster::coordinator::new_test_running_cluster(
            self_id,
            fresh_single_node_table,
            &[(self_id, "127.0.0.1:4802".parse().unwrap())],
            &[self_id],
            &[],
            &[],
            &[],
            restored.peak_cluster_size as usize,
        );
        let item = WireCreateItem {
            txid: DispatchTestHarness::make_txid(82),
            tx_version: 1,
            locktime: 0,
            fee: 500,
            size_in_bytes: 250,
            extended_size: 250,
            is_coinbase: false,
            spending_height: 0,
            created_at: 1700000000000,
            flags: 0,
            utxo_hashes: vec![DispatchTestHarness::make_txid(83)],
            cold_data: vec![],
            block_height: 0,
            mined_block_id: None,
            mined_block_height: None,
            mined_subtree_idx: None,
            parent_txids: vec![],
        };
        let resp = h.request_with_cluster(
            OP_CREATE_BATCH,
            encode_create_batch(&[item]),
            &rebooted_cluster,
        );
        assert_eq!(
            resp.status, STATUS_ERROR,
            "node with deleted .topo and prior multi-node marker must not accept fresh single-node writes",
        );
        assert!(resp.payload.len() >= 2);
        let err_code = u16::from_le_bytes(resp.payload[..2].try_into().unwrap());
        assert_eq!(err_code, ERR_NO_QUORUM);
    }

    // -----------------------------------------------------------------------
    // Phase 1: observability counters + latency histograms
    //
    // These tests exercise the instrumentation inside each `handle_*_batch`
    // handler. They all share a single process-global `ThreadMetrics`
    // because DISPATCH_METRICS is a OnceLock — so each test takes
    // `METRICS_TEST_LOCK` and snapshots counter deltas instead of relying
    // on absolute values.
    // -----------------------------------------------------------------------

    use crate::metrics::{ThreadHistograms, ThreadMetrics};
    use std::sync::{Mutex as StdMutex, OnceLock};

    /// Lazily-initialized global test metrics. Installed into DISPATCH_METRICS
    /// on first access; subsequent accesses return the same reference.
    fn test_metrics() -> &'static ThreadMetrics {
        static INIT: OnceLock<&'static ThreadMetrics> = OnceLock::new();
        INIT.get_or_init(|| {
            let leaked: &'static ThreadMetrics = Box::leak(Box::new(ThreadMetrics::new()));
            super::init_dispatch_metrics(leaked);
            leaked
        })
    }

    fn test_histograms() -> &'static ThreadHistograms {
        static INIT: OnceLock<&'static ThreadHistograms> = OnceLock::new();
        INIT.get_or_init(|| {
            let leaked: &'static ThreadHistograms = Box::leak(Box::new(ThreadHistograms::new()));
            super::init_dispatch_histograms(leaked);
            leaked
        })
    }

    /// Serialize metrics-observing tests so concurrent increments from
    /// neighbours do not pollute each test's delta. `Mutex` is fine here;
    /// if a test panics the poison is cleared manually.
    fn metrics_test_lock() -> std::sync::MutexGuard<'static, ()> {
        static LOCK: OnceLock<StdMutex<()>> = OnceLock::new();
        match LOCK.get_or_init(|| StdMutex::new(())).lock() {
            Ok(g) => g,
            Err(poisoned) => poisoned.into_inner(),
        }
    }

    /// Capture the current counter values as a named tuple for delta math.
    fn snapshot_spend(m: &ThreadMetrics) -> (u64, u64, u64, u64, u64) {
        (
            m.spend_multi_items_attempted.get(),
            m.spend_multi_items_succeeded.get(),
            m.spend_multi_items_idempotent.get(),
            m.spend_multi_items_failed.get(),
            m.spend_multi_batches.get(),
        )
    }

    fn snapshot_unspend(m: &ThreadMetrics) -> (u64, u64, u64, u64, u64) {
        (
            m.unspend_multi_items_attempted.get(),
            m.unspend_multi_items_succeeded.get(),
            m.unspend_multi_items_idempotent.get(),
            m.unspend_multi_items_failed.get(),
            m.unspend_multi_batches.get(),
        )
    }

    /// Submit a spend batch with three items: two valid, one with a wrong
    /// utxo_hash. Assert the per-item counters advance by (3, 2, 0, 1).
    #[test]
    fn handle_spend_batch_increments_items_succeeded_and_failed() {
        let m = test_metrics();
        let _ = test_histograms();

        let h = DispatchTestHarness::new();
        let txid_a = DispatchTestHarness::make_txid(40);
        let txid_b = DispatchTestHarness::make_txid(41);
        let txid_c = DispatchTestHarness::make_txid(42);
        assert_eq!(h.create_tx(txid_a, 2).status, STATUS_OK);
        assert_eq!(h.create_tx(txid_b, 2).status, STATUS_OK);
        assert_eq!(h.create_tx(txid_c, 2).status, STATUS_OK);

        // Hash generated by create_tx for vout=0 is all-zeros with the
        // low-order nibble encoding the vout.
        let utxo_hash_vout0 = [0u8; 32];
        // Deliberately wrong hash for item C — will produce UtxoHashMismatch.
        let wrong_hash = [0xEEu8; 32];
        let params = SpendBatchParams {
            ignore_conflicting: false,
            ignore_locked: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let items = vec![
            WireSpendItem {
                txid: txid_a,
                vout: 0,
                utxo_hash: utxo_hash_vout0,
                spending_data: [0xA1; 36],
            },
            WireSpendItem {
                txid: txid_b,
                vout: 0,
                utxo_hash: utxo_hash_vout0,
                spending_data: [0xB2; 36],
            },
            WireSpendItem {
                txid: txid_c,
                vout: 0,
                utxo_hash: wrong_hash,
                spending_data: [0xC3; 36],
            },
        ];
        let before = snapshot_spend(m);
        let resp = h.request(OP_SPEND_BATCH, encode_spend_batch(&params, &items));
        let after = snapshot_spend(m);

        // Expect STATUS_PARTIAL_ERROR because one item failed validation.
        assert_eq!(resp.status, STATUS_PARTIAL_ERROR);
        assert_eq!(after.0 - before.0, 3, "items_attempted += 3");
        assert_eq!(after.1 - before.1, 2, "items_succeeded += 2");
        assert_eq!(after.2 - before.2, 0, "no idempotent items");
        assert_eq!(after.3 - before.3, 1, "items_failed += 1 (hash mismatch)");
        assert_eq!(after.4 - before.4, 1, "one batch processed");
    }

    /// P0 (consensus-critical double-spend): a STANDALONE segment spend must be
    /// recoverable from the durable REDO ALONE. An acked spend RELOCATES the record
    /// and bakes the spent slot into the new image; under buffered durability those
    /// relocated bytes sit in the drive's volatile cache until the next CHECKPOINT
    /// fsyncs them, while the background flusher makes the redo durable first. A
    /// power-loss in that window must NOT revert the acked spend to UNSPENT (a
    /// double-spend).
    ///
    /// Before the fix a standalone segment spend journaled only a THIN
    /// `RedoOp::Relocate` pointing at the new (still-buffered) offset. On recovery
    /// `replay_relocate` read those lost bytes, found them torn, and `Skipped` —
    /// keeping the index on the intact PRE-spend record, so the slot read UNSPENT
    /// again and the acked spend was silently undone. The fix makes the standalone
    /// segment spend emit the self-sufficient per-vout `RedoOp::SpendV2` (like
    /// clustered) and stops journaling the thin Relocate, so recovery replays the
    /// spend IN PLACE against the durable, append-only pre-spend record — no
    /// dependence on the lost relocated bytes. Mirrors the clustered recovery test
    /// `clustered_segment_spendv2_reconstructs_spend_in_place`.
    #[test]
    fn standalone_segment_spend_recoverable_from_redo_alone_after_powerloss() {
        let _mg = metrics_test_lock();

        // STANDALONE segment engine + one redo log — the SAME Arc wired to both the
        // engine's internal redo path (`set_redo_logs`, used by `relocate_record`)
        // and the dispatch redo_log param, exactly as production does (server.rs).
        // Buffered durability = the bug's config.
        let dev: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(64 * 1024 * 1024, 4096).unwrap());
        let seg =
            crate::segment_allocator::SegmentAllocator::new(dev.clone(), 8 * 1024 * 1024).unwrap();
        let engine = Engine::new(
            dev.clone(),
            Index::new(1024).unwrap(),
            seg,
            StripedLocks::new(64),
            DahIndex::new(),
        );
        assert!(
            engine.store_is_log_structured(0),
            "segment (log-structured)"
        );

        let redo_size: u64 = 8 * 1024 * 1024;
        let redo_dev: Arc<dyn BlockDevice> = Arc::new(MemoryDevice::new(redo_size, 4096).unwrap());
        let log = Arc::new(Mutex::new(
            RedoLog::open(redo_dev.clone(), 0, redo_size).unwrap(),
        ));
        engine.set_redo_logs(vec![log.clone()]);
        engine.set_buffered_durability(true);

        // Durable, checkpoint-covered PRE-spend record at offset X: 4 UTXOs, all
        // UNSPENT. `write_full_record` stamps valid metadata + slot CRCs.
        let utxo_count = 4u32;
        let mut txid = [0u8; 32];
        txid[0] = 0x9A;
        let key = TxKey { txid };
        let mut slot1_hash = [0u8; 32];
        slot1_hash[0] = 0x11;
        slot1_hash[1] = 0x22; // the hash the spend of vout 1 will match
        let slots: Vec<crate::record::UtxoSlot> = (0..utxo_count)
            .map(|i| {
                if i == 1 {
                    crate::record::UtxoSlot::new_unspent(slot1_hash)
                } else {
                    let mut h = [0u8; 32];
                    h[0] = (i as u8) + 1;
                    crate::record::UtxoSlot::new_unspent(h)
                }
            })
            .collect();
        let mut meta = crate::record::TxMetadata::new(utxo_count);
        meta.tx_id = txid;
        let rec_size = crate::record::TxMetadata::record_size_for(utxo_count);
        let x = engine.allocator_for(0).lock().allocate(rec_size).unwrap();
        crate::io::write_full_record(&*dev, x, &meta, &slots).unwrap();
        engine
            .register(
                key,
                crate::index::TxIndexEntry {
                    device_id: 0,
                    record_offset: x,
                    mined_slot: crate::index::mined_index::NO_MINED_SLOT,
                },
            )
            .unwrap();

        // Drive a REAL spend of vout 1 through the dispatch path — this exercises the
        // `emit_spend_v2` decision AND `relocate_record`. It relocates X -> Y
        // (buffered) and journals the spend's redo.
        let params = SpendBatchParams {
            ignore_conflicting: true,
            ignore_locked: true,
            current_block_height: 1000,
            block_height_retention: 0,
        };
        let spending_data = [0x5Cu8; 36];
        let items = vec![WireSpendItem {
            txid,
            vout: 1,
            utxo_hash: slot1_hash,
            spending_data,
        }];
        let req = RequestFrame {
            request_id: 1,
            op_code: OP_SPEND_BATCH,
            flags: 0,
            payload: encode_spend_batch(&params, &items).into(),
        };
        let mut conn_state = crate::server::ConnectionState::new();
        let resp = handle_request(
            &req,
            &engine,
            8192,
            None,
            Some(&*log),
            &mut conn_state,
            None,
        );
        assert_eq!(resp.status, STATUS_OK, "single valid spend must be acked");

        // The live spend relocated the record off X.
        let y = engine.lookup(&key).unwrap().record_offset;
        assert_ne!(y, x, "segment spend relocates the record");

        // Make the REDO durable — the fsync the buffered ack path skipped.
        log.lock().flush().unwrap();

        // The emitted spend redo must be the self-sufficient SpendV2, NOT the thin
        // Relocate: the spend is recoverable from the redo alone.
        let entries = {
            let l = RedoLog::open(redo_dev.clone(), 0, redo_size).unwrap();
            l.recover().unwrap()
        };
        let has_spend_v2 = entries.iter().any(|e| {
            matches!(&e.op, RedoOp::SpendV2 { tx_key, offset, .. } if *tx_key == key && *offset == 1)
        });
        let has_relocate = entries
            .iter()
            .any(|e| matches!(&e.op, RedoOp::Relocate { tx_key, .. } if *tx_key == key));
        assert!(
            has_spend_v2,
            "standalone segment spend must journal a self-sufficient SpendV2",
        );
        assert!(
            !has_relocate,
            "standalone segment spend must NOT journal a thin Relocate for the spend",
        );

        // POWER LOSS: the buffered data-device write at Y is lost (never fsynced),
        // while the durable pre-spend record at X survives (append-only never
        // overwrote it) and the index reloads from the pre-spend checkpoint snapshot
        // (index -> X). Model this with a FRESH device holding ONLY the pre-spend
        // record at X (Y absent) and a fresh index pointed at X — the same
        // redo-is-the-only-truth setup as the strict clustered recovery test.
        let recov_dev: Arc<dyn BlockDevice> =
            Arc::new(MemoryDevice::new(64 * 1024 * 1024, 4096).unwrap());
        crate::io::write_full_record(&*recov_dev, x, &meta, &slots).unwrap();
        let recov_index = crate::index::ShardedIndex::from_single(Index::new(1024).unwrap().into());
        recov_index
            .register(
                key,
                crate::index::TxIndexEntry {
                    device_id: 0,
                    record_offset: x,
                    mined_slot: crate::index::mined_index::NO_MINED_SLOT,
                },
            )
            .unwrap();
        let rec_log = RedoLog::open(redo_dev.clone(), 0, redo_size).unwrap();
        let stats = crate::recovery::recover(&*recov_dev, &rec_log, &recov_index).unwrap();
        assert_eq!(stats.entries_failed, 0, "no fatal replay failures");

        // The acked spend SURVIVED power-loss: the record stays indexed at the
        // durable pre-spend offset X and is reconstructed SPENT there — NOT reverted
        // to UNSPENT (which would be a double-spend).
        let ie = recov_index.lookup(&key).expect("record still indexed");
        assert_eq!(ie.record_offset, x, "SpendV2 replays in place at X");
        let m = crate::io::read_metadata(&*recov_dev, x).unwrap();
        assert_eq!(
            { m.spent_utxos },
            1,
            "acked spend survived power-loss (recovered from redo alone), NOT reverted to UNSPENT",
        );
        let s = crate::io::read_all_utxo_slots(&*recov_dev, x, utxo_count).unwrap();
        assert_eq!(s[1].status, crate::record::UTXO_SPENT, "vout 1 SPENT");
        assert_eq!(s[1].spending_data, spending_data, "spending data preserved");
        assert_eq!(s[0].status, crate::record::UTXO_UNSPENT, "vout 0 untouched");
    }

    #[test]
    fn pruned_utxo_spend_returns_original_spending_data() {
        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(44);
        assert_eq!(h.create_tx(txid, 1).status, STATUS_OK);

        let key = TxKey { txid };
        let entry = h.engine.lookup(&key).unwrap();
        let utxo_hash = [0u8; 32];
        let spending_data = [0x5Au8; 36];
        let mut pruned_slot = crate::record::UtxoSlot::new_spent(utxo_hash, spending_data);
        pruned_slot.status = crate::record::UTXO_PRUNED;
        crate::io::write_utxo_slot(h.engine.device(), entry.record_offset, 0, &pruned_slot)
            .unwrap();

        let params = SpendBatchParams {
            ignore_conflicting: false,
            ignore_locked: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        // F-G2-002: avoid the reserved all-`0xFF` sentinel for the
        // request's spending_data; that triggers the
        // `ReservedSpendingData` rejection (ERR_INVALID_SPEND with
        // empty payload) before the engine ever reads the slot, so
        // the pruned-spending-data forensic payload never surfaces.
        let item = WireSpendItem {
            txid,
            vout: 0,
            utxo_hash,
            spending_data: [0xEE; 36],
        };

        let resp = h.request(OP_SPEND_BATCH, encode_spend_batch(&params, &[item]));
        assert_eq!(resp.status, STATUS_PARTIAL_ERROR);
        let errors = decode_sparse_errors(&resp.payload).unwrap();
        assert_eq!(errors.len(), 1);
        assert_eq!(errors[0].item_index, 0);
        assert_eq!(errors[0].error_code, ERR_INVALID_SPEND);
        assert_eq!(errors[0].error_data, spending_data.to_vec());
    }

    /// Re-sending the exact same spend should classify the second send as
    /// idempotent rather than succeeded or failed.
    #[test]
    fn handle_spend_batch_idempotent_counted_as_idempotent() {
        let m = test_metrics();
        let _ = test_histograms();

        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(43);
        assert_eq!(h.create_tx(txid, 1).status, STATUS_OK);

        let utxo_hash_vout0 = [0u8; 32];
        let params = SpendBatchParams {
            ignore_conflicting: false,
            ignore_locked: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let item = WireSpendItem {
            txid,
            vout: 0,
            utxo_hash: utxo_hash_vout0,
            spending_data: [0xAB; 36],
        };

        // First spend: succeeds.
        let before1 = snapshot_spend(m);
        let r1 = h.request(
            OP_SPEND_BATCH,
            encode_spend_batch(&params, std::slice::from_ref(&item)),
        );
        let after1 = snapshot_spend(m);
        assert_eq!(r1.status, STATUS_OK);
        assert_eq!(after1.1 - before1.1, 1, "first spend: 1 success");
        assert_eq!(after1.2 - before1.2, 0, "first spend: 0 idempotent");

        // Second identical spend: idempotent.
        let before2 = snapshot_spend(m);
        let r2 = h.request(
            OP_SPEND_BATCH,
            encode_spend_batch(&params, std::slice::from_ref(&item)),
        );
        let after2 = snapshot_spend(m);
        assert_eq!(r2.status, STATUS_OK);
        assert_eq!(after2.0 - before2.0, 1, "items_attempted += 1");
        assert_eq!(after2.1 - before2.1, 0, "second spend: no new success");
        assert_eq!(after2.2 - before2.2, 1, "second spend: 1 idempotent");
        assert_eq!(after2.3 - before2.3, 0, "second spend: no failures");
    }

    /// Unspend should classify each item as succeeded (real unspend),
    /// idempotent (already-unspent noop), or failed (hash mismatch).
    #[test]
    fn handle_unspend_batch_ticks_outcome_counters() {
        let m = test_metrics();
        let _ = test_histograms();

        let h = DispatchTestHarness::new();
        let txid_a = DispatchTestHarness::make_txid(50);
        let txid_b = DispatchTestHarness::make_txid(51);
        let txid_c = DispatchTestHarness::make_txid(52);
        assert_eq!(h.create_tx(txid_a, 1).status, STATUS_OK);
        assert_eq!(h.create_tx(txid_b, 1).status, STATUS_OK);
        assert_eq!(h.create_tx(txid_c, 1).status, STATUS_OK);

        // Spend txid_a first so the subsequent unspend is a real unspend
        // (the other two are never spent → unspend is an idempotent no-op).
        let utxo_hash_vout0 = [0u8; 32];
        let sp = SpendBatchParams {
            ignore_conflicting: false,
            ignore_locked: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let spend_item = WireSpendItem {
            txid: txid_a,
            vout: 0,
            utxo_hash: utxo_hash_vout0,
            spending_data: [0x77; 36],
        };
        assert_eq!(
            h.request(OP_SPEND_BATCH, encode_spend_batch(&sp, &[spend_item]))
                .status,
            STATUS_OK,
        );

        // Now submit unspend for A (real), B (noop), and C with wrong hash (fail).
        let wrong_hash = [0x88u8; 32];
        let items = vec![
            WireUnspendItem {
                txid: txid_a,
                vout: 0,
                utxo_hash: utxo_hash_vout0,
                spending_data: [0x77; 36],
            },
            WireUnspendItem {
                txid: txid_b,
                vout: 0,
                utxo_hash: utxo_hash_vout0,
                spending_data: [0; 36],
            },
            WireUnspendItem {
                txid: txid_c,
                vout: 0,
                utxo_hash: wrong_hash,
                spending_data: [0; 36],
            },
        ];
        let params = UnspendBatchParams {
            current_block_height: 1000,
            block_height_retention: 288,
        };

        let before = snapshot_unspend(m);
        let resp = h.request(OP_UNSPEND_BATCH, encode_unspend_batch(&params, &items));
        let after = snapshot_unspend(m);
        assert_eq!(resp.status, STATUS_PARTIAL_ERROR);
        assert_eq!(after.0 - before.0, 3, "items_attempted += 3");
        assert_eq!(after.1 - before.1, 1, "items_succeeded += 1 (A)");
        assert_eq!(after.2 - before.2, 1, "items_idempotent += 1 (B)");
        assert_eq!(after.3 - before.3, 1, "items_failed += 1 (C wrong hash)");
        assert_eq!(after.4 - before.4, 1, "one unspend batch");
    }

    /// Unspend with spending data that does NOT match the stored spend is a
    /// silent idempotent no-op (`STATUS_OK`), NOT an error — matching the Lua
    /// `unspend` contract (`teranode.lua:513-540`): "never wipe a spend we
    /// don't own", not "error on every no-op". The stored spend belongs to the
    /// original spender, so the slot and counter must remain untouched, and the
    /// Go `ProcessConflicting` loop (which aborts on any non-OK status other
    /// than `TX_NOT_FOUND`) must see success.
    #[test]
    fn handle_unspend_batch_mismatch_is_noop_ok_not_error() {
        let m = test_metrics();
        let _ = test_histograms();

        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(53);
        assert_eq!(h.create_tx(txid, 1).status, STATUS_OK);

        let params = SpendBatchParams {
            ignore_conflicting: false,
            ignore_locked: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let stored_spending_data = [0x91; 36];
        let spend_item = WireSpendItem {
            txid,
            vout: 0,
            utxo_hash: [0; 32],
            spending_data: stored_spending_data,
        };
        assert_eq!(
            h.request(OP_SPEND_BATCH, encode_spend_batch(&params, &[spend_item]))
                .status,
            STATUS_OK,
        );

        // Counter is 1 spent UTXO after the spend.
        let spent_before = h
            .engine
            .read_metadata(&TxKey { txid })
            .expect("metadata readable")
            .spent_utxos;
        assert_eq!({ spent_before }, 1);

        let unspend_params = UnspendBatchParams {
            current_block_height: 1000,
            block_height_retention: 288,
        };
        // Spending data 0x92.. belongs to a different tx than the stored 0x91..
        let unspend_item = WireUnspendItem {
            txid,
            vout: 0,
            utxo_hash: [0; 32],
            spending_data: [0x92; 36],
        };
        let before = snapshot_unspend(m);
        let resp = h.request(
            OP_UNSPEND_BATCH,
            encode_unspend_batch(&unspend_params, &[unspend_item]),
        );
        let after = snapshot_unspend(m);

        // No-op success: STATUS_OK with an empty (error-free) payload.
        assert_eq!(resp.status, STATUS_OK);
        assert!(
            resp.payload.is_empty(),
            "mismatch must not produce a per-item error payload"
        );

        // Classified as idempotent, not succeeded, not failed.
        assert_eq!(after.0 - before.0, 1, "items_attempted += 1");
        assert_eq!(after.1 - before.1, 0, "no real unspend");
        assert_eq!(after.2 - before.2, 1, "idempotent += 1");
        assert_eq!(after.3 - before.3, 0, "no failures");

        // Slot still spent by the original spender; counter unchanged.
        let slot = h
            .engine
            .read_slot(&TxKey { txid }, 0)
            .expect("slot must remain readable");
        assert!(slot.is_spent());
        assert_eq!(slot.spending_data, stored_spending_data);
        let spent_after = h
            .engine
            .read_metadata(&TxKey { txid })
            .expect("metadata readable")
            .spent_utxos;
        assert_eq!({ spent_after }, 1, "spent counter must be untouched");
    }

    /// Helper: decode a `OP_SET_MINED_BATCH` response payload into its
    /// (successes, errors) sections, failing the test on a malformed payload.
    fn decode_set_mined_response(payload: &[u8]) -> (Vec<BatchItemSuccess>, Vec<BatchItemError>) {
        decode_partial_with_signals(payload)
            .expect("set_mined response payload must decode as partial-with-signals")
    }

    /// LP-2 / spec §3.6: a successful setMined must return the post-op block-ID
    /// list on the wire. Before the fix the handler returned an empty payload
    /// (errors-only `batch_response_with_outcome`), so this asserts the exact
    /// block-ID bytes the Go client (`txmetacache.SetMinedMulti`) consumes.
    #[test]
    fn set_mined_response_carries_block_ids() {
        let _m = test_metrics();
        let _ = test_histograms();

        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(80);
        assert_eq!(h.create_tx(txid, 1).status, STATUS_OK);

        let params = SetMinedBatchParams {
            block_id: 42,
            block_height: 100,
            subtree_idx: 0,
            on_longest_chain: true,
            unset_mined: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let payload = encode_set_mined_batch(&params, &[txid]);
        let resp = h.request(OP_SET_MINED_BATCH, payload);
        assert_eq!(resp.status, STATUS_OK);

        let (successes, errors) = decode_set_mined_response(&resp.payload);
        assert!(errors.is_empty(), "no item should fail");
        assert_eq!(successes.len(), 1, "exactly one success record");
        assert_eq!(successes[0].item_index, 0);
        // The current-block-IDs list must contain exactly the mined block.
        assert_eq!(
            successes[0].block_ids,
            vec![42],
            "response must carry the post-op block-ID list"
        );
        // A fresh single-UTXO mine is not all-spent → no DAH transition →
        // Signal::None (wire byte 0). Pins the LP-5 signal behavior.
        assert_eq!(
            successes[0].signal,
            crate::ops::signal::Signal::None.to_wire(),
            "fresh non-all-spent mine emits no signal"
        );
    }

    /// A tx mined into multiple blocks (reorg / parallel chains) must return
    /// the full current block-ID list, in insertion order.
    #[test]
    fn set_mined_multiple_blocks_returns_all_block_ids() {
        let _m = test_metrics();
        let _ = test_histograms();

        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(81);
        assert_eq!(h.create_tx(txid, 1).status, STATUS_OK);

        let mk = |block_id: u32, on_longest: bool| SetMinedBatchParams {
            block_id,
            block_height: 100 + block_id,
            subtree_idx: 0,
            on_longest_chain: on_longest,
            unset_mined: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };

        // Mine into block 42 (longest chain) then block 43 (a side chain).
        let r1 = h.request(
            OP_SET_MINED_BATCH,
            encode_set_mined_batch(&mk(42, true), &[txid]),
        );
        assert_eq!(r1.status, STATUS_OK);
        let (s1, _) = decode_set_mined_response(&r1.payload);
        assert_eq!(s1[0].block_ids, vec![42]);

        let r2 = h.request(
            OP_SET_MINED_BATCH,
            encode_set_mined_batch(&mk(43, false), &[txid]),
        );
        assert_eq!(r2.status, STATUS_OK);
        let (s2, _) = decode_set_mined_response(&r2.payload);
        assert_eq!(
            s2[0].block_ids,
            vec![42, 43],
            "second mine must return both current block IDs"
        );
    }

    /// unsetMined must return the block-ID list with the removed block gone.
    /// Also pins the design decision that no childCount field is emitted: the
    /// payload decodes cleanly as exactly (success, error) sections with the
    /// remaining block IDs and nothing trailing.
    #[test]
    fn unset_mined_response_reflects_removal() {
        let _m = test_metrics();
        let _ = test_histograms();

        let h = DispatchTestHarness::new();
        let txid = DispatchTestHarness::make_txid(82);
        assert_eq!(h.create_tx(txid, 1).status, STATUS_OK);

        let set = |block_id: u32, on_longest: bool, unset: bool| SetMinedBatchParams {
            block_id,
            block_height: 100 + block_id,
            subtree_idx: 0,
            on_longest_chain: on_longest,
            unset_mined: unset,
            current_block_height: 1000,
            block_height_retention: 288,
        };

        // Mine into 42 and 43.
        assert_eq!(
            h.request(
                OP_SET_MINED_BATCH,
                encode_set_mined_batch(&set(42, true, false), &[txid])
            )
            .status,
            STATUS_OK
        );
        assert_eq!(
            h.request(
                OP_SET_MINED_BATCH,
                encode_set_mined_batch(&set(43, false, false), &[txid])
            )
            .status,
            STATUS_OK
        );

        // Unset block 42; the response must reflect only block 43 remaining.
        let r = h.request(
            OP_SET_MINED_BATCH,
            encode_set_mined_batch(&set(42, true, true), &[txid]),
        );
        assert_eq!(r.status, STATUS_OK);
        let (successes, errors) = decode_set_mined_response(&r.payload);
        assert!(errors.is_empty());
        assert_eq!(successes.len(), 1);
        assert_eq!(
            successes[0].block_ids,
            vec![43],
            "unset must drop the removed block ID from the response"
        );
        // The payload is exactly the partial-with-signals form: re-encoding the
        // decoded sections reproduces it byte-for-byte. No childCount/#1037
        // field is present — by design (pagination eliminated; master lock is
        // cleared server-side), so there is nothing trailing for the client to
        // mis-parse.
        let reencoded = encode_partial_with_signals(&successes, &errors);
        assert_eq!(
            reencoded, r.payload,
            "response must be exactly the partial-with-signals form, no extra fields"
        );
    }

    /// SetMined items should tick attempted/succeeded/failed per item.
    #[test]
    fn handle_set_mined_batch_ticks_outcome_counters() {
        let m = test_metrics();
        let _ = test_histograms();

        let h = DispatchTestHarness::new();
        let txid_a = DispatchTestHarness::make_txid(60);
        let txid_b = DispatchTestHarness::make_txid(61);
        assert_eq!(h.create_tx(txid_a, 1).status, STATUS_OK);
        assert_eq!(h.create_tx(txid_b, 1).status, STATUS_OK);
        // txid_c is NOT created — set_mined on it must fail with TxNotFound.
        let txid_c = DispatchTestHarness::make_txid(62);

        let params = SetMinedBatchParams {
            block_id: 42,
            block_height: 100,
            subtree_idx: 0,
            on_longest_chain: true,
            unset_mined: false,
            current_block_height: 1000,
            block_height_retention: 288,
        };
        let before_att = m.set_mined_items_attempted.get();
        let before_succ = m.set_mined_items_succeeded.get();
        let before_fail = m.set_mined_items_failed.get();

        let payload = encode_set_mined_batch(&params, &[txid_a, txid_b, txid_c]);
        let resp = h.request(OP_SET_MINED_BATCH, payload);
        assert_eq!(resp.status, STATUS_PARTIAL_ERROR);

        let after_att = m.set_mined_items_attempted.get();
        let after_succ = m.set_mined_items_succeeded.get();
        let after_fail = m.set_mined_items_failed.get();
        assert_eq!(after_att - before_att, 3, "set_mined_items_attempted += 3");
        assert_eq!(
            after_succ - before_succ,
            2,
            "set_mined_items_succeeded += 2"
        );
        assert_eq!(after_fail - before_fail, 1, "set_mined_items_failed += 1");
    }

